# I'll need to create my own minimal jpeglib.h header from the known API
# The jpeglib API is well-documented and stable. Let me write it based on the standard API
# and then compile. 

# First let me verify what functions we need and their signatures
# based on the jpeglib 8.0 ABI

# Let me write a minimal jpeglib.h that covers what we need for jp2a
cat > /tmp/test_jpeg.c << 'EOF'
// Test if we can link against libjpeg using our own header
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <setjmp.h>
#include <stdint.h>

// Minimal jpeglib.h equivalent
typedef unsigned char JSAMPLE;
typedef JSAMPLE *JSAMPROW;
typedef JSAMPROW *JSAMPARRAY;
typedef int JDIMENSION;

#define JPEG_LIB_VERSION 80
#define LIBJPEG_TURBO_VERSION_NUMBER 0

typedef enum { 
    JCS_UNKNOWN, JCS_GRAYSCALE, JCS_RGB, JCS_YCbCr, JCS_CMYK, JCS_YCCK
} J_COLOR_SPACE;

typedef enum {
    JPEG_SUSPENDED, JPEG_HEADER_OK, JPEG_HEADER_TABLES_ONLY
} jpeg_header_result;

struct jpeg_error_mgr;
struct jpeg_memory_mgr;
struct jpeg_progress_mgr;
struct jpeg_destination_mgr;
struct jpeg_source_mgr;

typedef void (*jpeg_error_exit_ptr)(struct jpeg_common_struct *);
typedef void (*jpeg_emit_message_ptr)(struct jpeg_common_struct *, int);
typedef void (*jpeg_output_message_ptr)(struct jpeg_common_struct *);
typedef void (*jpeg_format_message_ptr)(struct jpeg_common_struct *, char *);
typedef void (*jpeg_reset_error_mgr_ptr)(struct jpeg_common_struct *);

struct jpeg_error_mgr {
    jpeg_error_exit_ptr error_exit;
    jpeg_emit_message_ptr emit_message;
    jpeg_output_message_ptr output_message;
    jpeg_format_message_ptr format_message;
    jpeg_reset_error_mgr_ptr reset_error_mgr;
    int msg_code;
    union {
        int i[8];
        char s[80];
    } msg_parm;
    int trace_level;
    long num_warnings;
    const char * const * jpeg_message_table;
    int last_jpeg_message;
    const char * const * addon_message_table;
    int first_addon_message;
    int last_addon_message;
};

struct jpeg_common_struct {
    struct jpeg_error_mgr *err;
    struct jpeg_memory_mgr *mem;
    struct jpeg_progress_mgr *progress;
    void *client_data;
    int is_decompressor;
    int global_state;
};

struct jpeg_decompress_struct {
    struct jpeg_error_mgr *err;
    struct jpeg_memory_mgr *mem;
    struct jpeg_progress_mgr *progress;
    void *client_data;
    int is_decompressor;
    int global_state;
    struct jpeg_source_mgr *src;
    JDIMENSION image_width;
    JDIMENSION image_height;
    int num_components;
    J_COLOR_SPACE jpeg_color_space;
    J_COLOR_SPACE out_color_space;
    unsigned int scale_num, scale_denom;
    double output_gamma;
    int buffered_image;
    int raw_data_out;
    int dct_method;
    int do_fancy_upsampling;
    int do_block_smoothing;
    int quantize_colors;
    int dither_mode;
    int two_pass_quantize;
    int desired_number_of_colors;
    int enable_1pass_quant;
    int enable_external_quant;
    int enable_2pass_quant;
    JDIMENSION output_width;
    JDIMENSION output_height;
    int out_color_components;
    int output_components;
    int rec_outbuf_height;
    int actual_number_of_colors;
    // ... more fields
    unsigned long char_800[256];  // color map placeholder
    JDIMENSION output_scanline;
    int input_scan_number;
    JDIMENSION input_iMCU_row;
    int output_scan_number;
    JDIMENSION output_iMCU_row;
    int (*coef_bits)[64]; // ptr
    // Many more fields follow - padding to be safe
    char pad[1024];
};

// Error handler with setjmp support
struct my_error_mgr {
    struct jpeg_error_mgr pub;
    jmp_buf setjmp_buffer;
};

// Function declarations
extern struct jpeg_error_mgr * jpeg_std_error(struct jpeg_error_mgr *err);
extern void jpeg_CreateDecompress(struct jpeg_decompress_struct *cinfo, int version, size_t structsize);
extern void jpeg_stdio_src(struct jpeg_decompress_struct *cinfo, FILE *infile);
extern int jpeg_read_header(struct jpeg_decompress_struct *cinfo, int require_image);
extern int jpeg_start_decompress(struct jpeg_decompress_struct *cinfo);
extern JDIMENSION jpeg_read_scanlines(struct jpeg_decompress_struct *cinfo, JSAMPARRAY scanlines, JDIMENSION max_lines);
extern int jpeg_finish_decompress(struct jpeg_decompress_struct *cinfo);
extern void jpeg_destroy_decompress(struct jpeg_decompress_struct *cinfo);

#define jpeg_create_decompress(cinfo) jpeg_CreateDecompress((cinfo), JPEG_LIB_VERSION, sizeof(struct jpeg_decompress_struct))

static void my_error_exit(struct jpeg_common_struct *cinfo) {
    struct my_error_mgr *myerr = (struct my_error_mgr *)cinfo->err;
    longjmp(myerr->setjmp_buffer, 1);
}

int main() {
    struct jpeg_decompress_struct cinfo;
    struct my_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr.pub);
    jerr.pub.error_exit = my_error_exit;

    if (setjmp(jerr.setjmp_buffer)) {
        jpeg_destroy_decompress(&cinfo);
        fprintf(stderr, "Error in JPEG\n");
        return 1;
    }

    jpeg_create_decompress(&cinfo);

    FILE *f = fopen("assets/grind.jpg", "rb");
    if (!f) { fprintf(stderr, "Can't open file\n"); return 1; }

    jpeg_stdio_src(&cinfo, f);
    jpeg_read_header(&cinfo, 1);

    printf("Width: %d, Height: %d, Components: %d\n", 
           cinfo.image_width, cinfo.image_height, cinfo.num_components);

    jpeg_destroy_decompress(&cinfo);
    fclose(f);
    return 0;
}
EOF

gcc -o /tmp/test_jpeg /tmp/test_jpeg.c -L/usr/lib/x86_64-linux-gnu -ljpeg 2>&1

