    struct jpeg_error_mgr *err;        // 8 bytes
    struct jpeg_memory_mgr *mem;       // 8 bytes
    struct jpeg_progress_mgr *progress; // 8 bytes
    void *client_data;                  // 8 bytes
    int is_decompressor;               // 4 bytes
    int global_state;                  // 4 bytes
    // 40 bytes used for common
    struct jpeg_source_mgr *src;       // 8 bytes = 48
    JDIMENSION image_width;            // 4 bytes = 56
    JDIMENSION image_height;           // 4 bytes = 60
    int num_components;                // 4 bytes = 64
    J_COLOR_SPACE jpeg_color_space;    // 4 bytes = 68
    J_COLOR_SPACE out_color_space;     // 4 bytes = 72
    unsigned int scale_num;            // 4 bytes = 76
    unsigned int scale_denom;          // 4 bytes = 80
    double output_gamma;               // 8 bytes = 88
    int buffered_image;                // 4 bytes = 92
    int raw_data_out;                  // 4 bytes = 96
    int dct_method;                    // 4 bytes = 100
    int do_fancy_upsampling;           // 4 bytes = 104
    int do_block_smoothing;            // 4 bytes = 108
    int quantize_colors;               // 4 bytes = 112
    int dither_mode;                   // 4 bytes = 116
    int two_pass_quantize;             // 4 bytes = 120
    int desired_number_of_colors;      // 4 bytes = 124
    int enable_1pass_quant;            // 4 bytes = 128
    int enable_external_quant;         // 4 bytes = 132
    int enable_2pass_quant;            // 4 bytes = 136
    // Output parameters
    JDIMENSION output_width;           // 4 bytes = 140
    JDIMENSION output_height;          // 4 bytes = 144
    int out_color_components;          // 4 bytes = 148
    int output_components;             // 4 bytes = 152
    int rec_outbuf_height;             // 4 bytes = 156
    int actual_number_of_colors;       // 4 bytes = 160
    // Remainder - padding
    char pad[2048];
};

#define JPEG_LIB_VERSION 80

