int jpeg_start_decompress(struct jpeg_decompress_struct *cinfo);
JDIMENSION jpeg_read_scanlines(struct jpeg_decompress_struct *cinfo, JSAMPARRAY scanlines, JDIMENSION max_lines);
int jpeg_finish_decompress(struct jpeg_decompress_struct *cinfo);
void jpeg_destroy_decompress(struct jpeg_decompress_struct *cinfo);

