    uint32_t h = *(uint32_t*)(cinfo + 140);
    int comps = *(int*)(cinfo + 148);
    uint8_t *buf = malloc(w * comps);
    uint8_t *rows[1] = {buf};
    for (uint32_t row = 0; row < h && row < 2; row++) {
        jpeg_read_scanlines(cinfo, rows, 1);
        printf("Row %u (comps=%d): ", row, comps);
        for (uint32_t x = 0; x < w && x < 5; x++) {
            if (comps == 1) printf("(%d) ", buf[x]);
            else printf("(%d,%d,%d) ", buf[x*comps], buf[x*comps+1], buf[x*comps+2]);
        }
        printf("\n");
