} opts;

/* ====== ANSI color functions ====== */

/* Returns ANSI color code string (without ESC prefix) based on R,G,B values */
static const char *rgb_to_ansi(int r, int g, int b) {
    int max_ch, second_max;
    /* Find if one channel is clearly dominant */
    /* Threshold: dominant - second_max >= 26 */
    int rg = abs(r - g);
    int rb = abs(r - b);
    int gb = abs(g - b);

    /* Find max channel */
    int mx = r;
    if (g > mx) mx = g;
    if (b > mx) mx = b;

    /* Find second max */
    if (mx == r) {
        second_max = (g > b) ? g : b;
        if (g == mx) {
            /* R=G >= B: yellow or ... */
            if (r - b >= 26 && g - b >= 26) return "33"; /* yellow */
            if (rg < 26) return "37"; /* gray */
        }
        if (b == mx) {
            /* R=B >= G: magenta or ... */
            if (r - g >= 26 && b - g >= 26) return "35"; /* magenta */
            if (rb < 26) return "37"; /* gray */
        }
        if (r - second_max >= 26) return "31"; /* red */
    } else if (mx == g) {
        second_max = (r > b) ? r : b;
        if (g == b && b == mx) {
            /* G=B >= R: cyan */
            if (g - r >= 26 && b - r >= 26) return "36"; /* cyan */
            if (gb < 26) return "37";
        }
        if (r == mx) {
            /* G=R */
            if (g - b >= 26 && r - b >= 26) return "33"; /* yellow */
            if (rg < 26) return "37";
        }
        if (g - second_max >= 26) return "32"; /* green */
    } else { /* b == mx */
        second_max = (r > g) ? r : g;
        if (b == r && r == mx) {
            /* B=R >= G: magenta */
            if (b - g >= 26 && r - g >= 26) return "35"; /* magenta */
            if (rb < 26) return "37";
        }
        if (b == g && g == mx) {
            /* B=G >= R: cyan */
            if (b - r >= 26 && g - r >= 26) return "36"; /* cyan */
            if (gb < 26) return "37";
        }
        if (b - second_max >= 26) return "34"; /* blue */
    }
    return "37"; /* default white/gray */
}

/* Test ANSI color selection */
static const char *get_ansi_color(int r, int g, int b) {
    /* Find min and max */
    int mn = r, mx = r;
    if (g < mn) mn = g; if (g > mx) mx = g;
    if (b < mn) mn = b; if (b > mx) mx = b;

    /* If max - min < threshold, it's gray */
    if (mx - mn < 26) return "37"; /* white/gray */

    /* Determine dominant channel(s) */
    /* Which channels are "near max" (within threshold of max)? */
    int r_near = (mx - r < 26);
    int g_near = (mx - g < 26);
    int b_near = (mx - b < 26);

    if (r_near && g_near && !b_near) return "33"; /* yellow */
    if (r_near && b_near && !g_near) return "35"; /* magenta */
    if (g_near && b_near && !r_near) return "36"; /* cyan */
    if (r_near && !g_near && !b_near) return "31"; /* red */
    if (g_near && !r_near && !b_near) return "32"; /* green */
    if (b_near && !r_near && !g_near) return "34"; /* blue */

    return "37"; /* all near max = white/gray */
}

/* ====== Pixel data storage ====== */

typedef struct {
    int r, g, b;
    int lum;  /* 0..255 */
} pixel_t;

/* ====== Image processing ====== */

static float compute_luminance(int r, int g, int b) {
    return opts.red_weight * r + opts.green_weight * g + opts.blue_weight * b;
}

/* Map luminance (0..255) to palette character index (0..palette_len-1) */
static int lum_to_idx(int lum) {
    int n = opts.palette_len;
    int idx = (int)round((float)lum * (n - 1) / 255.0f);
    if (idx < 0) idx = 0;
    if (idx >= n) idx = n - 1;
    return idx;
}

static char lum_to_char(int lum, int invert) {
    int idx = lum_to_idx(lum);
    if (invert) idx = opts.palette_len - 1 - idx;
    return opts.palette[idx];
}

/* ====== HTML output ====== */

static void html_print_header(FILE *out) {
    fprintf(out, "<?xml version='1.0' encoding='ISO-8859-1'?>\n");
    fprintf(out, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  "
            "'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n");
    fprintf(out, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n");
    fprintf(out, "<head>\n");
    fprintf(out, "<title>%s</title>\n", opts.html_title ? opts.html_title : "jp2a converted image");
    fprintf(out, "<style type='text/css'>\n");
    fprintf(out, "body {\n");
    if (opts.background_light)
        fprintf(out, "   background-color: white;\n");
    else
        fprintf(out, "background-color: black;\n");
    fprintf(out, "}\n");
    fprintf(out, ".ascii {\n");
    fprintf(out, "   font-family: Courier;\n");
    if (!opts.colors && !opts.grayscale) {
        if (opts.background_light)
            fprintf(out, "   color: black;\n");
        else
            fprintf(out, "   color: white;\n");
    }
    fprintf(out, "   font-size:%dpt;\n", opts.html_fontsize);
    if (opts.html_no_bold)
        fprintf(out, "   font-weight: normal;\n");
    else
        fprintf(out, "   font-weight: bold;\n");
    fprintf(out, "}\n");
    fprintf(out, "</style>\n");
    fprintf(out, "</head>\n");
    fprintf(out, "<body>\n");
    fprintf(out, "<div class='ascii'><pre>\n");
}

static void html_print_footer(FILE *out) {
    fprintf(out, "</pre>\n");
    fprintf(out, "</div>\n");
    fprintf(out, "</body>\n");
    fprintf(out, "</html>\n");
}

static void html_escape(FILE *out, char c) {
    if (c == ' ')
        fprintf(out, "&nbsp;");
    else if (c == '<')
        fprintf(out, "&lt;");
    else if (c == '>')
        fprintf(out, "&gt;");
    else if (c == '&')
        fprintf(out, "&amp;");
    else
        fputc(c, out);
}

/* ====== Main image processing ====== */

static int get_term_size(int *w, int *h) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0) {
        *w = ws.ws_col;
        *h = ws.ws_row;
        return 1;
    }
    return 0;
}

static void calc_dimensions(int src_w, int src_h, int *out_w, int *out_h) {
    /* Output dimensions account for border */
    int border_adjust = opts.border ? 2 : 0;

    if (opts.term_zoom) {
        int tw, th;
        if (get_term_size(&tw, &th)) {
            *out_w = tw - border_adjust;
            *out_h = th - border_adjust;
        } else {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = 80 - border_adjust;
            *out_h = 25 - border_adjust;
        }
        return;
    }

    if (opts.term_fit) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = 0;
            *out_h = 0;
            return;
        }
        tw -= border_adjust;
        th -= border_adjust;
        if (tw <= 0) tw = 1;
        if (th <= 0) th = 1;
        /* Scale to fit in tw x th while maintaining aspect ratio */
        /* Note: chars are ~2x taller than wide, so adjust */
        float aspect = (float)src_w / src_h;
        /* Try width-limited */
        int h_from_w = (int)(tw / aspect / 2.0f + 0.5f);  /* /2 for char aspect */
        /* Try height-limited */
        int w_from_h = (int)(th * aspect * 2.0f + 0.5f);  /* *2 for char aspect */

        if (h_from_w <= th) {
            *out_w = tw;
            *out_h = h_from_w;
        } else {
            *out_w = w_from_h;
            *out_h = th;
        }
        return;
    }

    if (opts.term_width) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = 0; *out_h = 0;
            return;
        }
        *out_w = tw - border_adjust;
        *out_h = (int)((float)*out_w * src_h / src_w / 2.0f + 0.5f);
        return;
    }

    if (opts.term_height) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = 0; *out_h = 0;
            return;
        }
        *out_h = th - border_adjust;
        *out_w = (int)((float)*out_h * src_w / src_h * 2.0f + 0.5f);
        return;
    }

    if (opts.use_width && opts.use_height) {
        *out_w = opts.width;
        *out_h = opts.height;
        return;
    }

    if (opts.use_width) {
        *out_w = opts.width;
        *out_h = (int)((float)opts.width * src_h / src_w / 2.0f + 0.5f);
        if (*out_h == 0) *out_h = 1;
        return;
    }

    if (opts.use_height) {
        *out_h = opts.height;
        *out_w = (int)((float)opts.height * src_w / src_h * 2.0f + 0.5f);
        if (*out_w == 0) *out_w = 1;
        return;
    }

    /* Default: term-fit mode */
    opts.term_fit = 1;
    calc_dimensions(src_w, src_h, out_w, out_h);
    opts.term_fit = 0;
}

static void print_verbose(jpeg_decompress_struct *cinfo, int out_w, int out_h) {
    fprintf(stderr, "Source width: %d\n", cinfo->image_width);
    fprintf(stderr, "Source height: %d\n", cinfo->image_height);
    fprintf(stderr, "Source color components: %d\n", cinfo->num_components);
    fprintf(stderr, "Output width: %d\n", out_w);
    fprintf(stderr, "Output height: %d\n", out_h);
    fprintf(stderr, "Output palette (%d chars): '%s'\n", opts.palette_len, opts.palette);
}

/* Print progress bar to stderr (for verbose mode) */
static void print_progress(int current_line, int total_lines) {
    int bar_width = 54;
    int filled = (int)((float)current_line * bar_width / total_lines);
    fprintf(stderr, "\rDecompressing image [");
    for (int i = 0; i < bar_width; i++) {
        if (i < filled) fputc('#', stderr);
        else fputc('.', stderr);
    }
    fprintf(stderr, "]");
}

/* Process a single JPEG image */
static int process_image(const char *filename, FILE *in_fp, FILE *out_fp) {
    jpeg_decompress_struct cinfo;
    struct my_error_mgr jerr;
    JSAMPARRAY row_buffer = NULL;
    pixel_t **image = NULL;
    int out_w = 0, out_h = 0;
    int ret = 0;

    cinfo.err = jpeg_std_error(&jerr.pub);
    jerr.pub.error_exit = my_error_exit;

    if (setjmp(jerr.setjmp_buffer)) {
        ret = 1;
        goto cleanup;
    }

    jpeg_create_decompress(&cinfo);

    if (in_fp) {
        jpeg_stdio_src(&cinfo, in_fp);
    } else {
        /* filename is used as URL - not supported in this impl */
        fprintf(stderr, "URL support not available\n");
        return 1;
    }

    jpeg_read_header(&cinfo, 1);

    /* Calculate output dimensions */
    calc_dimensions(cinfo.image_width, cinfo.image_height, &out_w, &out_h);

    if (out_w <= 0 || out_h <= 0) {
        jpeg_destroy_decompress(&cinfo);
        return 1;
    }

    if (opts.verbose) {
        if (filename)
            fprintf(stderr, "File: %s\n", filename);
        print_verbose(&cinfo, out_w, out_h);
    }

    jpeg_start_decompress(&cinfo);

    int src_w = cinfo.output_width;
    int src_h = cinfo.output_height;
    int src_comps = cinfo.output_components;

    /* Allocate output image buffer */
    image = (pixel_t **)malloc(out_h * sizeof(pixel_t *));
    for (int y = 0; y < out_h; y++) {
        image[y] = (pixel_t *)calloc(out_w, sizeof(pixel_t));
    }

    /* Allocate row buffer for JPEG */
    row_buffer = (JSAMPARRAY)malloc(sizeof(JSAMPROW));
    row_buffer[0] = (JSAMPROW)malloc(src_w * src_comps);

    /* Read all scanlines and sample to output dimensions */
    /* For each output row y, we need source row y_src = y * src_h / out_h */
    /* For each output col x, we need source col x_src = x * src_w / out_w */

    /* We'll read all source rows and sample */
    /* Count how many samples per output row */
    int *row_counts = (int *)calloc(out_h, sizeof(int));
    long *row_lum_sums = NULL;  /* if we average */

    /* Simple approach: collect samples per output pixel */
    /* For each source row, determine which output row(s) it maps to */

    /* Two separate accumulators for R, G, B, count */
    int *sum_r = (int *)calloc(out_h * out_w, sizeof(int));
    int *sum_g = (int *)calloc(out_h * out_w, sizeof(int));
    int *sum_b = (int *)calloc(out_h * out_w, sizeof(int));
    int *count = (int *)calloc(out_h * out_w, sizeof(int));

    int src_y = 0;

    while (cinfo.output_scanline < cinfo.output_height) {
        int current_line = cinfo.output_scanline;

        if (opts.verbose) {
            print_progress(current_line, src_h);
        }

        jpeg_read_scanlines(&cinfo, row_buffer, 1);

        /* Which output rows does this source row contribute to? */
        /* Source row current_line maps to output row: current_line * out_h / src_h */
        int out_y = current_line * out_h / src_h;
        if (out_y >= out_h) out_y = out_h - 1;

        JSAMPLE *row = row_buffer[0];

        for (int x = 0; x < out_w; x++) {
            /* Which source x does this output x map to? */
            int src_x = x * src_w / out_w;
            if (src_x >= src_w) src_x = src_w - 1;

            int idx = out_y * out_w + x;

            if (src_comps == 1) {
                int v = row[src_x];
                sum_r[idx] += v;
                sum_g[idx] += v;
                sum_b[idx] += v;
            } else {
                sum_r[idx] += row[src_x * src_comps];
                sum_g[idx] += row[src_x * src_comps + 1];
                sum_b[idx] += row[src_x * src_comps + 2];
            }
            count[idx]++;
        }

        src_y++;
    }

    if (opts.verbose) {
        print_progress(src_h, src_h);
        fprintf(stderr, "\n");
    }

    /* Compute final pixel values */
    for (int y = 0; y < out_h; y++) {
        for (int x = 0; x < out_w; x++) {
            int idx = y * out_w + x;
            int c = count[idx];
            if (c > 0) {
                image[y][x].r = sum_r[idx] / c;
                image[y][x].g = sum_g[idx] / c;
                image[y][x].b = sum_b[idx] / c;
            }
            float lum = compute_luminance(image[y][x].r, image[y][x].g, image[y][x].b);
            image[y][x].lum = (int)(lum + 0.5f);
            if (image[y][x].lum < 0) image[y][x].lum = 0;
            if (image[y][x].lum > 255) image[y][x].lum = 255;
        }
    }

    /* Handle clear screen */
    if (opts.clear && !opts.html) {
        fprintf(out_fp, "\033[2J\033[0;0H");
    }

    /* Print HTML header if needed */
    if (opts.html && !opts.html_raw) {
        html_print_header(out_fp);
    }

    /* Print border top */
    if (opts.border && !opts.html) {
        fprintf(out_fp, "+");
        for (int x = 0; x < out_w; x++) fputc('-', out_fp);
        fprintf(out_fp, "+\n");
    }

    /* Print image */
    int is_grayscale = (cinfo.num_components == 1);

    for (int y = 0; y < out_h; y++) {
        if (opts.border && !opts.html) fputc('|', out_fp);

        if (opts.html) fprintf(out_fp, "");  /* newline handled by <br/> */

        for (int x = 0; x < out_w; x++) {
            /* Determine actual x based on flipx */
            int sx = opts.flipx ? (out_w - 1 - x) : x;
            int sy = opts.flipy ? (out_h - 1 - y) : y;

            pixel_t *p = &image[sy][sx];
            int lum = p->lum;
            char ch = lum_to_char(lum, opts.invert);

            if (opts.html) {
                /* HTML output */
                if (opts.colors || opts.grayscale) {
                    int r = p->r, g = p->g, b = p->b;
                    if (opts.grayscale) {
                        r = g = b = lum;
                    }
                    if (opts.html_fill) {
                        /* Compute background color (slightly different) */
                        /* The fill color is a blend/modification */
                        /* Based on observation: fill background is like average */
                        int bg_r = (r + 255) / 2;
                        int bg_g = (g + 255) / 2;
                        int bg_b = (b + 255) / 2;
                        /* Actually looking at HTML output: bg is like lum mapped */
                        /* Let me use a simpler model based on observed output */
                        fprintf(out_fp, "<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>",
                                r, g, b, bg_r, bg_g, bg_b);
                    } else {
                        fprintf(out_fp, "<span style='color:#%02x%02x%02x;'>", r, g, b);
                    }
                    html_escape(out_fp, ch);
                    fprintf(out_fp, "</span>");
                } else {
                    html_escape(out_fp, ch);
                }
            } else {
                /* Text output with optional ANSI colors */
                if (opts.colors && !opts.grayscale) {
                    /* RGB color mode */
                    if (is_grayscale) {
                        /* 1-component grayscale: special bold/white handling */
                        if (lum == 0) {
                            fprintf(out_fp, "\033[37m%c\033[0m", ch);
                        } else if (lum >= 243) {
                            fprintf(out_fp, "\033[1m%c\033[0m", ch);
                        } else {
                            fputc(ch, out_fp);
                        }
                    } else {
                        /* 3-component: use RGB color */
                        const char *code = get_ansi_color(p->r, p->g, p->b);
                        fprintf(out_fp, "\033[%sm%c\033[0m", code, ch);
                    }
                } else if (opts.grayscale || (opts.colors && opts.grayscale)) {
                    /* Grayscale mode: ESC[37m for bright values */
                    if (lum >= 179) {
                        fprintf(out_fp, "\033[37m%c\033[0m", ch);
                    } else {
                        fputc(ch, out_fp);
                    }
                } else {
                    fputc(ch, out_fp);
                }
            }
        }

        if (opts.html) {
            fprintf(out_fp, "<br/>");
        } else {
            if (opts.border) fputc('|', out_fp);
            fputc('\n', out_fp);
        }
    }

    if (opts.html) {
        fprintf(out_fp, "\n");
    }

    /* Print border bottom */
    if (opts.border && !opts.html) {
        fprintf(out_fp, "+");
        for (int x = 0; x < out_w; x++) fputc('-', out_fp);
        fprintf(out_fp, "+\n");
    }

    /* Print HTML footer */
    if (opts.html && !opts.html_raw) {
        html_print_footer(out_fp);
    }

    free(sum_r); free(sum_g); free(sum_b); free(count);
    free(row_counts);

cleanup:
    if (row_buffer) {
        free(row_buffer[0]);
        free(row_buffer);
    }
    if (image) {
        for (int y = 0; y < out_h; y++) {
            if (image[y]) free(image[y]);
        }
        free(image);
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    return ret;
}

