        if (h_from_w <= th) {
            *out_w = tw;
            *out_h = h_from_w;
        } else {
            *out_w = w_from_h;
            *out_h = th;
        }
        return;
    }

    if (opts.term_width) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = 0; *out_h = 0;
            return;
        }
        *out_w = tw - border_adjust;
        *out_h = (int)((float)*out_w * src_h / src_w / 2.0f + 0.5f);
        return;
    }

    if (opts.term_height) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = 0; *out_h = 0;
            return;
        }
        *out_h = th - border_adjust;
        *out_w = (int)((float)*out_h * src_w / src_h * 2.0f + 0.5f);
        return;
    }

    if (opts.use_width && opts.use_height) {
        *out_w = opts.width;
        *out_h = opts.height;
        return;
    }

    if (opts.use_width) {
        *out_w = opts.width;
        *out_h = (int)((float)opts.width * src_h / src_w / 2.0f + 0.5f);
        if (*out_h == 0) *out_h = 1;
        return;
    }

    if (opts.use_height) {
        *out_h = opts.height;
        *out_w = (int)((float)opts.height * src_w / src_h * 2.0f + 0.5f);
        if (*out_w == 0) *out_w = 1;
        return;
    }

    /* Default: term-fit mode */
    opts.term_fit = 1;
    calc_dimensions(src_w, src_h, out_w, out_h);
    opts.term_fit = 0;
}

static void print_verbose(jpeg_decompress_struct *cinfo, int out_w, int out_h) {
    fprintf(stderr, "Source width: %d\n", cinfo->image_width);
    fprintf(stderr, "Source height: %d\n", cinfo->image_height);
    fprintf(stderr, "Source color components: %d\n", cinfo->num_components);
    fprintf(stderr, "Output width: %d\n", out_w);
    fprintf(stderr, "Output height: %d\n", out_h);
    fprintf(stderr, "Output palette (%d chars): '%s'\n", opts.palette_len, opts.palette);
}

/* Print progress bar to stderr (for verbose mode) */
static void print_progress(int current_line, int total_lines) {
    int bar_width = 54;
    int filled = (int)((float)current_line * bar_width / total_lines);
    fprintf(stderr, "\rDecompressing image [");
    for (int i = 0; i < bar_width; i++) {
        if (i < filled) fputc('#', stderr);
        else fputc('.', stderr);
    }
    fprintf(stderr, "]");
}

/* Process a single JPEG image */
static int process_image(const char *filename, FILE *in_fp, FILE *out_fp) {
    jpeg_decompress_struct cinfo;
    struct my_error_mgr jerr;
    JSAMPARRAY row_buffer = NULL;
    pixel_t **image = NULL;
    int out_w = 0, out_h = 0;
    int ret = 0;

    cinfo.err = jpeg_std_error(&jerr.pub);
    jerr.pub.error_exit = my_error_exit;

    if (setjmp(jerr.setjmp_buffer)) {
        ret = 1;
        goto cleanup;
    }

    jpeg_create_decompress(&cinfo);

    if (in_fp) {
        jpeg_stdio_src(&cinfo, in_fp);
    } else {
        /* filename is used as URL - not supported in this impl */
        fprintf(stderr, "URL support not available\n");
        return 1;
    }

    jpeg_read_header(&cinfo, 1);

    /* Calculate output dimensions */
    calc_dimensions(cinfo.image_width, cinfo.image_height, &out_w, &out_h);

    if (out_w <= 0 || out_h <= 0) {
        jpeg_destroy_decompress(&cinfo);
        return 1;
    }

    if (opts.verbose) {
        if (filename)
            fprintf(stderr, "File: %s\n", filename);
        print_verbose(&cinfo, out_w, out_h);
    }

    jpeg_start_decompress(&cinfo);

    int src_w = cinfo.output_width;
    int src_h = cinfo.output_height;
    int src_comps = cinfo.output_components;

    /* Allocate output image buffer */
    image = (pixel_t **)malloc(out_h * sizeof(pixel_t *));
    for (int y = 0; y < out_h; y++) {
        image[y] = (pixel_t *)calloc(out_w, sizeof(pixel_t));
    }

    /* Allocate row buffer for JPEG */
    row_buffer = (JSAMPARRAY)malloc(sizeof(JSAMPROW));
    row_buffer[0] = (JSAMPROW)malloc(src_w * src_comps);

    /* Read all scanlines and sample to output dimensions */
    /* For each output row y, we need source row y_src = y * src_h / out_h */
    /* For each output col x, we need source col x_src = x * src_w / out_w */

    /* We'll read all source rows and sample */
    /* Count how many samples per output row */
    int *row_counts = (int *)calloc(out_h, sizeof(int));
    long *row_lum_sums = NULL;  /* if we average */

    /* Simple approach: collect samples per output pixel */
    /* For each source row, determine which output row(s) it maps to */

    /* Two separate accumulators for R, G, B, count */
    int *sum_r = (int *)calloc(out_h * out_w, sizeof(int));
    int *sum_g = (int *)calloc(out_h * out_w, sizeof(int));
    int *sum_b = (int *)calloc(out_h * out_w, sizeof(int));
    int *count = (int *)calloc(out_h * out_w, sizeof(int));

    int src_y = 0;

    while (cinfo.output_scanline < cinfo.output_height) {
        int current_line = cinfo.output_scanline;

        if (opts.verbose) {
            print_progress(current_line, src_h);
        }

        jpeg_read_scanlines(&cinfo, row_buffer, 1);

        /* Which output rows does this source row contribute to? */
        /* Source row current_line maps to output row: current_line * out_h / src_h */
        int out_y = current_line * out_h / src_h;
        if (out_y >= out_h) out_y = out_h - 1;

        JSAMPLE *row = row_buffer[0];

        for (int x = 0; x < out_w; x++) {
            /* Which source x does this output x map to? */
            int src_x = x * src_w / out_w;
            if (src_x >= src_w) src_x = src_w - 1;

            int idx = out_y * out_w + x;

            if (src_comps == 1) {
                int v = row[src_x];
                sum_r[idx] += v;
                sum_g[idx] += v;
                sum_b[idx] += v;
            } else {
                sum_r[idx] += row[src_x * src_comps];
                sum_g[idx] += row[src_x * src_comps + 1];
                sum_b[idx] += row[src_x * src_comps + 2];
            }
            count[idx]++;
        }

        src_y++;
    }

    if (opts.verbose) {
        print_progress(src_h, src_h);
        fprintf(stderr, "\n");
    }

    /* Compute final pixel values */
    for (int y = 0; y < out_h; y++) {
        for (int x = 0; x < out_w; x++) {
            int idx = y * out_w + x;
            int c = count[idx];
            if (c > 0) {
                image[y][x].r = sum_r[idx] / c;
                image[y][x].g = sum_g[idx] / c;
                image[y][x].b = sum_b[idx] / c;
            }
            float lum = compute_luminance(image[y][x].r, image[y][x].g, image[y][x].b);
            image[y][x].lum = (int)(lum + 0.5f);
            if (image[y][x].lum < 0) image[y][x].lum = 0;
            if (image[y][x].lum > 255) image[y][x].lum = 255;
        }
    }

    /* Handle clear screen */
    if (opts.clear && !opts.html) {
        fprintf(out_fp, "\033[2J\033[0;0H");
    }

    /* Print HTML header if needed */
    if (opts.html && !opts.html_raw) {
        html_print_header(out_fp);
    }

    /* Print border top */
    if (opts.border && !opts.html) {
        fprintf(out_fp, "+");
        for (int x = 0; x < out_w; x++) fputc('-', out_fp);
        fprintf(out_fp, "+\n");
    }

    /* Print image */
    int is_grayscale = (cinfo.num_components == 1);

    for (int y = 0; y < out_h; y++) {
        if (opts.border && !opts.html) fputc('|', out_fp);

        if (opts.html) fprintf(out_fp, "");  /* newline handled by <br/> */

        for (int x = 0; x < out_w; x++) {
            /* Determine actual x based on flipx */
            int sx = opts.flipx ? (out_w - 1 - x) : x;
            int sy = opts.flipy ? (out_h - 1 - y) : y;

            pixel_t *p = &image[sy][sx];
            int lum = p->lum;
            char ch = lum_to_char(lum, opts.invert);

            if (opts.html) {
                /* HTML output */
                if (opts.colors || opts.grayscale) {
                    int r = p->r, g = p->g, b = p->b;
                    if (opts.grayscale) {
                        r = g = b = lum;
                    }
                    if (opts.html_fill) {
                        /* Compute background color (slightly different) */
                        /* The fill color is a blend/modification */
                        /* Based on observation: fill background is like average */
                        int bg_r = (r + 255) / 2;
                        int bg_g = (g + 255) / 2;
                        int bg_b = (b + 255) / 2;
                        /* Actually looking at HTML output: bg is like lum mapped */
                        /* Let me use a simpler model based on observed output */
                        fprintf(out_fp, "<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>",
                                r, g, b, bg_r, bg_g, bg_b);
                    } else {
                        fprintf(out_fp, "<span style='color:#%02x%02x%02x;'>", r, g, b);
                    }
                    html_escape(out_fp, ch);
                    fprintf(out_fp, "</span>");
                } else {
                    html_escape(out_fp, ch);
                }
            } else {
                /* Text output with optional ANSI colors */
                if (opts.colors && !opts.grayscale) {
                    /* RGB color mode */
                    if (is_grayscale) {
                        /* 1-component grayscale: special bold/white handling */
                        if (lum == 0) {
                            fprintf(out_fp, "\033[37m%c\033[0m", ch);
                        } else if (lum >= 243) {
                            fprintf(out_fp, "\033[1m%c\033[0m", ch);
                        } else {
                            fputc(ch, out_fp);
                        }
                    } else {
                        /* 3-component: use RGB color */
                        const char *code = get_ansi_color(p->r, p->g, p->b);
                        fprintf(out_fp, "\033[%sm%c\033[0m", code, ch);
                    }
                } else if (opts.grayscale || (opts.colors && opts.grayscale)) {
                    /* Grayscale mode: ESC[37m for bright values */
                    if (lum >= 179) {
                        fprintf(out_fp, "\033[37m%c\033[0m", ch);
                    } else {
                        fputc(ch, out_fp);
                    }
                } else {
                    fputc(ch, out_fp);
                }
            }
        }

        if (opts.html) {
            fprintf(out_fp, "<br/>");
        } else {
            if (opts.border) fputc('|', out_fp);
            fputc('\n', out_fp);
        }
    }

    if (opts.html) {
        fprintf(out_fp, "\n");
    }

    /* Print border bottom */
    if (opts.border && !opts.html) {
        fprintf(out_fp, "+");
        for (int x = 0; x < out_w; x++) fputc('-', out_fp);
        fprintf(out_fp, "+\n");
    }

    /* Print HTML footer */
    if (opts.html && !opts.html_raw) {
        html_print_footer(out_fp);
    }

    free(sum_r); free(sum_g); free(sum_b); free(count);
    free(row_counts);

cleanup:
    if (row_buffer) {
        free(row_buffer[0]);
        free(row_buffer);
    }
    if (image) {
        for (int y = 0; y < out_h; y++) {
            if (image[y]) free(image[y]);
        }
        free(image);
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    return ret;
}

/* ====== Main ====== */

static void print_version(void) {
    fprintf(stdout, "jp2a %s\n", "1.0.8");
    fprintf(stdout, "Copyright 2006-2016 Christian Stigen Larsen\n");
    fprintf(stdout, "Distributed under the GNU General Public License (GPL) v2.\n");
}

static void print_help(void) {
    print_version();
    fprintf(stdout, "\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n\n");
    fprintf(stdout, "Convert files or URLs from JPEG format to ASCII.\n\n");
    fprintf(stdout, "OPTIONS\n");
    fprintf(stdout, "  -                 Read images from standard input.\n");
    fprintf(stdout, "      --blue=N.N    Set RGB to grayscale conversion weight, default is 0.1145\n");
    fprintf(stdout, "  -b, --border      Print a border around the output image.\n");
    fprintf(stdout, "      --chars=...   Select character palette used to paint the image.\n");
    fprintf(stdout, "                    Leftmost character corresponds to black pixel, right-\n");
    fprintf(stdout, "                    most to white.  Minimum two characters must be specified.\n");
    fprintf(stdout, "      --clear       Clears screen before drawing each output image.\n");
    fprintf(stdout, "      --colors      Use ANSI colors in output.\n");
    fprintf(stdout, "  -d, --debug       Print additional debug information.\n");
    fprintf(stdout, "      --fill        When used with --color and/or --html, color each character's\n");
    fprintf(stdout, "                    background color.\n");
    fprintf(stdout, "  -x, --flipx       Flip image in X direction.\n");
    fprintf(stdout, "  -y, --flipy       Flip image in Y direction.\n");
    fprintf(stdout, "  -f, --term-fit    Use the largest image dimension that fits in your terminal\n");
    fprintf(stdout, "                    display with correct aspect ratio.\n");
    fprintf(stdout, "      --term-height Use terminal display height.\n");
    fprintf(stdout, "      --term-width  Use terminal display width.\n");
    fprintf(stdout, "  -z, --term-zoom   Use terminal display dimension for output.\n");
    fprintf(stdout, "      --grayscale   Convert image to grayscale when using --html or --colors\n");
    fprintf(stdout, "      --green=N.N   Set RGB to grayscale conversion weight, default is 0.5866\n");
    fprintf(stdout, "      --height=N    Set output height, calculate width from aspect ratio.\n");
    fprintf(stdout, "  -h, --help        Print program help.\n");
    fprintf(stdout, "      --html        Produce strict XHTML 1.0 output.\n");
    fprintf(stdout, "      --html-fill   Same as --fill (will be phased out)\n");
    fprintf(stdout, "      --html-fontsize=N   Set fontsize to N pt, default is 4.\n");
    fprintf(stdout, "      --html-no-bold      Do not use bold characters with HTML output\n");
    fprintf(stdout, "      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.\n");
    fprintf(stdout, "      --html-title=...  Set HTML output title\n");
    fprintf(stdout, "  -i, --invert      Invert output image.  Use if your display has a dark\n");
    fprintf(stdout, "                    background.\n");
    fprintf(stdout, "      --background=dark   These are just mnemonics whether to use --invert\n");
    fprintf(stdout, "      --background=light  or not.  If your console has light characters on\n");
    fprintf(stdout, "                    a dark background, use --background=dark.\n");
    fprintf(stdout, "      --output=...  Write output to file.\n");
    fprintf(stdout, "      --red=N.N     Set RGB to grayscale conversion weight, default 0.2989f.\n");
    fprintf(stdout, "      --size=WxH    Set output width and height.\n");
    fprintf(stdout, "  -v, --verbose     Verbose output.\n");
    fprintf(stdout, "  -V, --version     Print program version.\n");
    fprintf(stdout, "      --width=N     Set output width, calculate height from ratio.\n");
    fprintf(stdout, "\n");
    fprintf(stdout, "  The default mode is `jp2a --term-fit --background=dark'.\n");
    fprintf(stdout, "  See the man-page for jp2a for more detailed help text.\n");
    fprintf(stdout, "\n");
    fprintf(stdout, "Project homepage on https://github.com/cslarsen/jp2a\n");
    fprintf(stdout, "Report bugs to <csl@csl.name>\n");
}

static int parse_args(int argc, char **argv) {
    /* Set defaults */
    opts.width = 80;
    opts.height = 25;
    opts.use_width = 0;
    opts.use_height = 0;
    opts.term_fit = 0;
    opts.term_width = 0;
    opts.term_height = 0;
    opts.term_zoom = 0;
    opts.border = 0;
    opts.invert = 0;
    opts.flipx = 0;
    opts.flipy = 0;
    opts.verbose = 0;
    opts.html = 0;
    opts.html_raw = 0;
    opts.html_fill = 0;
    opts.html_no_bold = 0;
    opts.html_fontsize = 4;
    opts.html_title = NULL;
    opts.colors = 0;
    opts.grayscale = 0;
    opts.clear = 0;
    opts.debug = 0;
    opts.palette = DEFAULT_PALETTE;
    opts.palette_len = DEFAULT_PALETTE_LEN;
    opts.red_weight = 0.2989f;
    opts.green_weight = 0.5866f;
    opts.blue_weight = 0.1145f;
    opts.output_file = NULL;
    opts.background_light = 0;

    return 0;
}

int main(int argc, char **argv) {
    parse_args(argc, argv);

    int has_files = 0;
    int read_stdin = 0;
    FILE *out_fp = stdout;

    /* First pass: parse options */
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];

        if (strcmp(arg, "--version") == 0 || strcmp(arg, "-V") == 0) {
            print_version();
            return 0;
        } else if (strcmp(arg, "--help") == 0 || strcmp(arg, "-h") == 0) {
            print_help();
            return 0;
        } else if (strcmp(arg, "--border") == 0 || strcmp(arg, "-b") == 0) {
            opts.border = 1;
        } else if (strcmp(arg, "--invert") == 0 || strcmp(arg, "-i") == 0) {
            opts.invert = 1;
        } else if (strcmp(arg, "--flipx") == 0 || strcmp(arg, "-x") == 0) {
            opts.flipx = 1;
        } else if (strcmp(arg, "--flipy") == 0 || strcmp(arg, "-y") == 0) {
            opts.flipy = 1;
        } else if (strcmp(arg, "--verbose") == 0 || strcmp(arg, "-v") == 0) {
            opts.verbose = 1;
        } else if (strcmp(arg, "--debug") == 0 || strcmp(arg, "-d") == 0) {
            opts.debug = 1;
        } else if (strcmp(arg, "--colors") == 0) {
            opts.colors = 1;
        } else if (strcmp(arg, "--grayscale") == 0) {
            opts.grayscale = 1;
        } else if (strcmp(arg, "--html") == 0) {
            opts.html = 1;
        } else if (strcmp(arg, "--html-raw") == 0) {
            opts.html_raw = 1;
            opts.html = 1;
        } else if (strcmp(arg, "--fill") == 0 || strcmp(arg, "--html-fill") == 0) {
            opts.html_fill = 1;
        } else if (strcmp(arg, "--html-no-bold") == 0) {
            opts.html_no_bold = 1;
        } else if (strcmp(arg, "--clear") == 0) {
            opts.clear = 1;
        } else if (strcmp(arg, "--term-fit") == 0 || strcmp(arg, "-f") == 0) {
            opts.term_fit = 1;
        } else if (strcmp(arg, "--term-width") == 0) {
            opts.term_width = 1;
        } else if (strcmp(arg, "--term-height") == 0) {
            opts.term_height = 1;
        } else if (strcmp(arg, "--term-zoom") == 0 || strcmp(arg, "-z") == 0) {
            opts.term_zoom = 1;
        } else if (strncmp(arg, "--width=", 8) == 0) {
            opts.width = atoi(arg + 8);
            opts.use_width = 1;
        } else if (strncmp(arg, "--height=", 9) == 0) {
            opts.height = atoi(arg + 9);
            opts.use_height = 1;
        } else if (strncmp(arg, "--size=", 7) == 0) {
            int w, h;
            if (sscanf(arg + 7, "%dx%d", &w, &h) == 2) {
                opts.width = w; opts.height = h;
                opts.use_width = 1; opts.use_height = 1;
            }
        } else if (strncmp(arg, "--chars=", 8) == 0) {
            opts.palette = arg + 8;
            opts.palette_len = strlen(opts.palette);
        } else if (strncmp(arg, "--html-fontsize=", 16) == 0) {
            opts.html_fontsize = atoi(arg + 16);
        } else if (strncmp(arg, "--html-title=", 13) == 0) {
            opts.html_title = arg + 13;
        } else if (strncmp(arg, "--output=", 9) == 0) {
            opts.output_file = arg + 9;
        } else if (strncmp(arg, "--red=", 6) == 0) {
            opts.red_weight = atof(arg + 6);
        } else if (strncmp(arg, "--green=", 8) == 0) {
            opts.green_weight = atof(arg + 8);
        } else if (strncmp(arg, "--blue=", 7) == 0) {
            opts.blue_weight = atof(arg + 7);
        } else if (strcmp(arg, "--background=light") == 0) {
            opts.background_light = 1;
            opts.invert = 1;
        } else if (strcmp(arg, "--background=dark") == 0) {
            opts.background_light = 0;
            /* dark means no invert - but --background=dark is the default */
        } else if (strcmp(arg, "-") == 0) {
            read_stdin = 1;
            has_files = 1;
        } else if (arg[0] != '-') {
            has_files = 1;
        }
    }

    /* Handle output file */
    if (opts.output_file) {
        if (strcmp(opts.output_file, "-") == 0) {
            out_fp = stdout;
        } else {
            out_fp = fopen(opts.output_file, "w");
            if (!out_fp) {
                fprintf(stderr, "Can't open %s for writing\n", opts.output_file);
                return 1;
            }
        }
    }

    /* Default mode: term-fit */
    if (!opts.term_fit && !opts.term_width && !opts.term_height && !opts.term_zoom &&
        !opts.use_width && !opts.use_height) {
        opts.term_fit = 1;
    }

    if (!has_files) {
        /* Check if term_fit without terminal produces error */
        if (opts.term_fit || opts.term_width || opts.term_height || opts.term_zoom) {
            int tw, th;
            if (!get_term_size(&tw, &th)) {
                fprintf(stderr, "Environment variable TERM not set.\n");
                return 1;
            }
        }
        return 0;
    }

    int errors = 0;

    /* Process files */
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];

        /* Skip options */
        if (arg[0] == '-' && arg[1] != '\0' && arg[1] != '-') {
            if (strcmp(arg, "-b") == 0 || strcmp(arg, "-i") == 0 ||
                strcmp(arg, "-x") == 0 || strcmp(arg, "-y") == 0 ||
                strcmp(arg, "-v") == 0 || strcmp(arg, "-d") == 0 ||
                strcmp(arg, "-f") == 0 || strcmp(arg, "-z") == 0 ||
                strcmp(arg, "-V") == 0 || strcmp(arg, "-h") == 0) {
                continue;
            }
            if (strcmp(arg, "-") == 0) {
                /* stdin */
                errors += process_image("stdin", stdin, out_fp);
                continue;
            }
            continue;
        }

        if (arg[0] == '-' && arg[1] == '-') {
            continue; /* Skip all --options */
        }

        if (arg[0] == '-') continue;

        /* It's a file */
        FILE *fp = fopen(arg, "rb");
        if (!fp) {
            fprintf(stderr, "Can't open %s\n", arg);
            errors++;
            continue;
        }
        errors += process_image(arg, fp, out_fp);
        fclose(fp);
    }

    if (opts.output_file && out_fp != stdout) {
        fclose(out_fp);
    }

    return errors ? 1 : 0;
}
