int main(int argc, char **argv) {
    parse_args(argc, argv);

    int has_files = 0;
    int read_stdin = 0;
    FILE *out_fp = stdout;

    /* First pass: parse options */
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];

        if (strcmp(arg, "--version") == 0 || strcmp(arg, "-V") == 0) {
