            opts.invert = 1;
        } else if (strcmp(arg, "--background=dark") == 0) {
            opts.background_light = 0;
            /* dark means no invert - but --background=dark is the default */
        } else if (strcmp(arg, "-") == 0) {
            read_stdin = 1;
            has_files = 1;
        } else if (arg[0] != '-') {
            has_files = 1;
        }
    }

    /* Handle output file */
    if (opts.output_file) {
        if (strcmp(opts.output_file, "-") == 0) {
            out_fp = stdout;
        } else {
            out_fp = fopen(opts.output_file, "w");
            if (!out_fp) {
                fprintf(stderr, "Can't open %s for writing\n", opts.output_file);
                return 1;
            }
        }
    }

    /* Default mode: term-fit */
    if (!opts.term_fit && !opts.term_width && !opts.term_height && !opts.term_zoom &&
        !opts.use_width && !opts.use_height) {
        opts.term_fit = 1;
    }

    if (!has_files) {
        /* Check if term_fit without terminal produces error */
        if (opts.term_fit || opts.term_width || opts.term_height || opts.term_zoom) {
            int tw, th;
            if (!get_term_size(&tw, &th)) {
                fprintf(stderr, "Environment variable TERM not set.\n");
                return 1;
            }
        }
        return 0;
    }

    int errors = 0;

    /* Process files */
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];

        /* Skip options */
        if (arg[0] == '-' && arg[1] != '\0' && arg[1] != '-') {
            if (strcmp(arg, "-b") == 0 || strcmp(arg, "-i") == 0 ||
                strcmp(arg, "-x") == 0 || strcmp(arg, "-y") == 0 ||
                strcmp(arg, "-v") == 0 || strcmp(arg, "-d") == 0 ||
                strcmp(arg, "-f") == 0 || strcmp(arg, "-z") == 0 ||
                strcmp(arg, "-V") == 0 || strcmp(arg, "-h") == 0) {
                continue;
            }
            if (strcmp(arg, "-") == 0) {
                /* stdin */
                errors += process_image("stdin", stdin, out_fp);
                continue;
            }
            continue;
        }

        if (arg[0] == '-' && arg[1] == '-') {
            continue; /* Skip all --options */
        }

        if (arg[0] == '-') continue;

        /* It's a file */
        FILE *fp = fopen(arg, "rb");
        if (!fp) {
            fprintf(stderr, "Can't open %s\n", arg);
            errors++;
            continue;
        }
        errors += process_image(arg, fp, out_fp);
        fclose(fp);
    }

    if (opts.output_file && out_fp != stdout) {
        fclose(out_fp);
    }

    return errors ? 1 : 0;
}
