#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <setjmp.h>
#include <stdint.h>
#include <math.h>

struct jpeg_error_mgr {
    void (*error_exit)(void *);
    void (*emit_message)(void *, int);
    void (*output_message)(void *);
    void (*format_message)(void *, char *);
    void (*reset_error_mgr)(void *);
    int msg_code;
    union { int i[8]; char s[80]; } msg_parm;
    int trace_level;
    long num_warnings;
    const char * const *jpeg_message_table;
    int last_jpeg_message;
    const char * const *addon_message_table;
    int first_addon_message;
    int last_addon_message;
};
struct my_error_mgr { struct jpeg_error_mgr pub; jmp_buf setjmp_buffer; };
static void my_error_exit(void *cinfo) {
    struct jpeg_error_mgr **err_ptr = (struct jpeg_error_mgr **)cinfo;
    struct my_error_mgr *myerr = (struct my_error_mgr *)(*err_ptr);
    longjmp(myerr->setjmp_buffer, 1);
}
extern struct jpeg_error_mgr *jpeg_std_error(struct jpeg_error_mgr *);
extern void jpeg_CreateDecompress(void *, int, size_t);
extern void jpeg_stdio_src(void *, FILE *);
extern int jpeg_read_header(void *, int);
extern int jpeg_start_decompress(void *);
extern unsigned jpeg_read_scanlines(void *, uint8_t **, unsigned);
extern int jpeg_finish_decompress(void *);
extern void jpeg_destroy_decompress(void *);
#define JPEG_LIB_VERSION 80
#define JPEG_STRUCT_SIZE 656

static const char *PALETTE = "   ...',;:clodxkO0KXNWM";
#define PLEN 23

int main() {
    struct my_error_mgr jerr;
    uint8_t *cinfo = calloc(1, JPEG_STRUCT_SIZE + 64);
    *(struct jpeg_error_mgr **)cinfo = &jerr.pub;
    jpeg_std_error(&jerr.pub);
    jerr.pub.error_exit = my_error_exit;

    if (setjmp(jerr.setjmp_buffer)) {
        jpeg_destroy_decompress(cinfo);
        free(cinfo);
        return 1;
    }

    jpeg_CreateDecompress(cinfo, JPEG_LIB_VERSION, JPEG_STRUCT_SIZE);
    FILE *f = fopen("assets/grind.jpg", "rb");
    jpeg_stdio_src(cinfo, f);
    jpeg_read_header(cinfo, 1);
    jpeg_start_decompress(cinfo);

    uint32_t src_w = *(uint32_t*)(cinfo + 136);
    uint32_t src_h = *(uint32_t*)(cinfo + 140);
    int comps = *(int*)(cinfo + 148);
    int out_w = 20, out_h = 5;

    // Read all scanlines into memory
    uint8_t **rows = malloc(src_h * sizeof(uint8_t*));
    for (uint32_t y = 0; y < src_h; y++) {
        rows[y] = malloc(src_w * comps);
        uint8_t *r = rows[y];
        jpeg_read_scanlines(cinfo, &r, 1);
    }

    printf("Source: %ux%u comps=%d\n", src_w, src_h, comps);

    // Method 1: Simple single-pixel sampling
    printf("\nMethod 1 (single pixel sampling):\n");
    for (int y = 0; y < out_h; y++) {
        int src_y = y * src_h / out_h;
        for (int x = 0; x < out_w; x++) {
            int src_x = x * src_w / out_w;
            uint8_t *p = rows[src_y] + src_x * comps;
            float lum = 0.2989f * p[0] + 0.5866f * p[1] + 0.1145f * p[2];
            int idx = (int)round(lum * (PLEN-1) / 255.0f);
            if (idx < 0) idx = 0;
            if (idx >= PLEN) idx = PLEN-1;
            putchar(PALETTE[idx]);
        }
        putchar('\n');
    }

    // Method 2: Averaging approach
    printf("\nMethod 2 (averaging):\n");
    for (int y = 0; y < out_h; y++) {
        for (int x = 0; x < out_w; x++) {
            float sum_lum = 0;
            int count = 0;
            for (int sy = y * src_h / out_h; sy < (y+1) * src_h / out_h; sy++) {
                int src_x = x * src_w / out_w;
                uint8_t *p = rows[sy] + src_x * comps;
                sum_lum += 0.2989f * p[0] + 0.5866f * p[1] + 0.1145f * p[2];
                count++;
            }
            if (count > 0) {
                float lum = sum_lum / count;
                int idx = (int)round(lum * (PLEN-1) / 255.0f);
                if (idx < 0) idx = 0;
                if (idx >= PLEN) idx = PLEN-1;
                putchar(PALETTE[idx]);
            }
        }
        putchar('\n');
    }

    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    fclose(f);
    for (uint32_t y = 0; y < src_h; y++) free(rows[y]);
    free(rows);
    free(cinfo);
    return 0;
}
