    for (int num_rows = 1; num_rows <= 48; num_rows++) {
        float sum = 0;
        for (int sy = 0; sy < num_rows; sy++) {
            uint8_t *p = rows[sy] + 0 * comps;
            sum += 0.2989f * p[0] + 0.5866f * p[1] + 0.1145f * p[2];
        }
        float avg = sum / num_rows;
        if (avg >= 22.4 && avg <= 34.7) {
            printf("  rows 0..%d (n=%d): avg_lum=%.2f -> '.'\n", num_rows-1, num_rows, avg);
        }
    }

    // Try different row counting for out row 0
    printf("\n\nFirst 20 rows at x=0 one at a time:\n");
    for (int sy = 0; sy < 20; sy++) {
        uint8_t *p = rows[sy] + 0 * comps;
        float lum = 0.2989f * p[0] + 0.5866f * p[1] + 0.1145f * p[2];
        printf("  row %d: (%d,%d,%d) lum=%.1f\n", sy, p[0], p[1], p[2], lum);
    }

    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    fclose(f);
    for (uint32_t y = 0; y < (uint32_t)src_h; y++) free(rows[y]);
    free(rows);
    free(cinfo);
    return 0;
}
