    jpeg_start_decompress(cinfo);
    uint32_t src_w = *(uint32_t*)(cinfo + 136);
    uint32_t src_h = *(uint32_t*)(cinfo + 140);
    int comps = *(int*)(cinfo + 148);

    uint8_t *row_buf = malloc(src_w * comps);
    uint8_t **rp = &row_buf;

    long *r_sum = calloc(out_h * out_w, sizeof(long));
    long *g_sum = calloc(out_h * out_w, sizeof(long));
    long *b_sum = calloc(out_h * out_w, sizeof(long));
    int *cnt = calloc(out_h * out_w, sizeof(int));

    for (uint32_t i = 0; i < src_h; i++) {
        jpeg_read_scanlines(cinfo, rp, 1);

        int out_y = i * out_h / src_h;
        int row_bkwd = (i * out_h % src_h == 0) && (out_y > 0);

        for (int x_out = 0; x_out < out_w; x_out++) {
            // SINGLE PIXEL per output column per row (skip X pixels)
            int src_x = x_out * src_w / out_w;

            uint8_t *p = row_buf + src_x * comps;
            int r, g, b;
            if (comps >= 3) { r=p[0]; g=p[1]; b=p[2]; }
            else { r=g=b=p[0]; }

            r_sum[out_y * out_w + x_out] += r;
            g_sum[out_y * out_w + x_out] += g;
            b_sum[out_y * out_w + x_out] += b;
            cnt[out_y * out_w + x_out]++;

            if (row_bkwd) {
                r_sum[(out_y-1) * out_w + x_out] += r;
                g_sum[(out_y-1) * out_w + x_out] += g;
                b_sum[(out_y-1) * out_w + x_out] += b;
                cnt[(out_y-1) * out_w + x_out]++;
            }
        }
    }

    for (int y = 0; y < out_h; y++) {
        for (int x = 0; x < out_w; x++) {
            int c = cnt[y * out_w + x];
            if (c == 0) { putchar(' '); continue; }
            float r = (float)r_sum[y * out_w + x] / c;
            float g = (float)g_sum[y * out_w + x] / c;
            float b = (float)b_sum[y * out_w + x] / c;
            float lum = 0.2989f * r + 0.5866f * g + 0.1145f * b;
            int idx = (int)round(lum * (PLEN-1) / 255.0f);
            if (idx < 0) idx = 0; if (idx >= PLEN) idx = PLEN-1;
            putchar(PALETTE[idx]);
        }
        putchar('\n');
    }

    free(r_sum); free(g_sum); free(b_sum); free(cnt);
    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    fclose(f);
    free(cinfo);
    free(row_buf);
    return 0;
}
