gcc -o /tmp/verify_simple /tmp/verify_simple.c -L/tmp -ljpeg -lm -Wl,-rpath,/usr/lib/x86_64-linux-gnu 2>&1
cd /workspace && /tmp/verify_simple assets/grind.jpg 20 5 2>&1
echo "Original:"
./executable --size=20x5 assets/grind.jpg 2>&1

