    jpeg_CreateDecompress(cinfo, JPEG_LIB_VERSION, JPEG_STRUCT_SIZE);
    FILE *f = fopen(fn, "rb");
    jpeg_stdio_src(cinfo, f);
    jpeg_read_header(cinfo, 1);
    jpeg_start_decompress(cinfo);
    uint32_t src_w = *(uint32_t*)(cinfo + 136);
    uint32_t src_h = *(uint32_t*)(cinfo + 140);
    int comps = *(int*)(cinfo + 148);

    uint8_t *row_buf = malloc(src_w * comps);
    uint8_t **rp = &row_buf;

    long *r_sum = calloc(out_h * out_w, sizeof(long));
    long *g_sum = calloc(out_h * out_w, sizeof(long));
    long *b_sum = calloc(out_h * out_w, sizeof(long));
    int *cnt = calloc(out_h * out_w, sizeof(int));

    int src_h_mid = src_h / 2;
    int out_h_mid = out_h / 2;
    int src_w_mid = src_w / 2;
    int out_w_mid = out_w / 2;

    for (uint32_t i = 0; i < src_h; i++) {
        jpeg_read_scanlines(cinfo, rp, 1);

        int out_y = i * out_h / src_h;
        // ROW: ASYMMETRIC
        int row_bkwd = (i * out_h % src_h == 0) && (out_y > 0) && ((int)i <= src_h_mid);
        int row_fwd = ((i+1) * out_h % src_h == 0) && (out_y < out_h-1) && (out_y >= out_h_mid);

        for (uint32_t j = 0; j < src_w; j++) {
            int out_x = j * out_w / src_w;
            // COL: ASYMMETRIC
            int col_bkwd = (j * out_w % src_w == 0) && (out_x > 0) && ((int)j <= src_w_mid);
            int col_fwd = ((j+1) * out_w % src_w == 0) && (out_x < out_w-1) && (out_x >= out_w_mid);

            uint8_t *p = row_buf + j * comps;
            int r, g, b;
            if (comps >= 3) { r=p[0]; g=p[1]; b=p[2]; }
            else { r=g=b=p[0]; }

            #define ADD(oy, ox) do { \
                if ((oy)>=0 && (oy)<out_h && (ox)>=0 && (ox)<out_w) { \
                    r_sum[(oy)*out_w+(ox)]+=r; g_sum[(oy)*out_w+(ox)]+=g; b_sum[(oy)*out_w+(ox)]+=b; \
                    cnt[(oy)*out_w+(ox)]++; \
                } \
            } while(0)

            ADD(out_y, out_x);
            if (row_bkwd) { ADD(out_y-1, out_x); }
            if (row_fwd) { ADD(out_y+1, out_x); }
            if (col_bkwd) { ADD(out_y, out_x-1); }
            if (col_fwd) { ADD(out_y, out_x+1); }
            if (row_bkwd && col_bkwd) ADD(out_y-1, out_x-1);
            if (row_bkwd && col_fwd) ADD(out_y-1, out_x+1);
            if (row_fwd && col_bkwd) ADD(out_y+1, out_x-1);
            if (row_fwd && col_fwd) ADD(out_y+1, out_x+1);
        }
    }

    for (int y = 0; y < out_h; y++) {
        for (int x = 0; x < out_w; x++) {
            int c = cnt[y * out_w + x];
            if (c == 0) { putchar(' '); continue; }
            float r = (float)r_sum[y*out_w+x]/c;
            float g = (float)g_sum[y*out_w+x]/c;
            float b = (float)b_sum[y*out_w+x]/c;
            float lum = 0.2989f*r + 0.5866f*g + 0.1145f*b;
            int idx = (int)round(lum * (PLEN-1) / 255.0f);
            if (idx < 0) idx = 0; if (idx >= PLEN) idx = PLEN-1;
            putchar(PALETTE[idx]);
        }
        putchar('\n');
    }

    free(r_sum); free(g_sum); free(b_sum); free(cnt);
    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    fclose(f);
    free(cinfo);
    free(row_buf);
    return 0;
}
