                return 1;
            }
        }
    }

    /* Default mode: term-fit */
    if (!opts.term_fit && !opts.term_width_flag && !opts.term_height_flag &&
        !opts.term_zoom && !opts.use_width && !opts.use_height) {
        opts.term_fit = 1;
    }

