    /* Process files */
    int errors = 0;
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];

        /* Skip recognized flags */
        if (strcmp(arg, "--border") == 0 || strcmp(arg, "-b") == 0 ||
