            continue;

        /* Skip options with values */
        if (strncmp(arg, "--width=", 8) == 0 || strncmp(arg, "--height=", 9) == 0 ||
            strncmp(arg, "--size=", 7) == 0 || strncmp(arg, "--chars=", 8) == 0 ||
            strncmp(arg, "--html-fontsize=", 16) == 0 || strncmp(arg, "--html-title=", 13) == 0 ||
            strncmp(arg, "--output=", 9) == 0 || strncmp(arg, "--red=", 6) == 0 ||
            strncmp(arg, "--green=", 8) == 0 || strncmp(arg, "--blue=", 7) == 0)
            continue;

        if (arg[0] == '-' && arg[1] == '-') continue; /* Unknown --option */

        /* stdin */
        if (strcmp(arg, "-") == 0) {
            errors += process_image("stdin", stdin, out_fp);
            continue;
        }

        /* Skip other single-char flags */
        if (arg[0] == '-' && arg[1] != '\0') continue;

        /* It's a filename */
        FILE *fp = fopen(arg, "rb");
        if (!fp) {
            fprintf(stderr, "Can't open %s\n", arg);
            errors++;
            continue;
        }
        errors += process_image(arg, fp, out_fp);
        fclose(fp);
    }

    if (opts.output_file && out_fp != stdout) {
        fclose(out_fp);
    }

    return errors ? 1 : 0;
