/* ====== Dimension calculation ====== */
static void calc_dimensions(int src_w, int src_h, int *out_w, int *out_h) {
    int border_adj = opts.border ? 2 : 0;

    if (opts.term_zoom) {
        int tw, th;
        if (get_term_size(&tw, &th)) {
            *out_w = tw - border_adj;
            *out_h = th - border_adj;
        } else {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = *out_h = 0;
        }
        return;
    }

    if (opts.term_fit) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = *out_h = 0;
            return;
        }
        tw -= border_adj; th -= border_adj;
        if (tw < 1) tw = 1;
        if (th < 1) th = 1;
        /* Fit in terminal with 2:1 char aspect ratio */
        float aspect = (float)src_w / src_h;
        int h_from_w = (int)(tw / aspect / 2.0f + 0.5f);
        int w_from_h = (int)(th * aspect * 2.0f + 0.5f);
        if (h_from_w <= th) {
            *out_w = tw; *out_h = h_from_w;
        } else {
            *out_w = w_from_h; *out_h = th;
        }
        if (*out_w < 1) *out_w = 1;
        if (*out_h < 1) *out_h = 1;
        return;
    }

    if (opts.term_width_flag) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = *out_h = 0;
            return;
        }
        *out_w = tw - border_adj;
        *out_h = (int)((float)*out_w * src_h / src_w / 2.0f + 0.5f);
        if (*out_h < 1) *out_h = 1;
        return;
    }

    if (opts.term_height_flag) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = *out_h = 0;
            return;
        }
        *out_h = th - border_adj;
        *out_w = (int)((float)*out_h * src_w / src_h * 2.0f + 0.5f);
        if (*out_w < 1) *out_w = 1;
        return;
    }

    if (opts.use_width && opts.use_height) {
        *out_w = opts.width; *out_h = opts.height;
        return;
    }
    if (opts.use_width) {
        *out_w = opts.width;
        *out_h = (int)((float)opts.width * src_h / src_w / 2.0f + 0.5f);
        if (*out_h < 1) *out_h = 1;
