                        int bg_g = (pg * 2 + 255) / 3;
                        int bg_b = (pb * 2 + 255) / 3;
                        fprintf(out_fp, "<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>",
                                pr, pg, pb, bg_r, bg_g, bg_b);
                    } else {
                        fprintf(out_fp, "<span style='color:#%02x%02x%02x;'>", pr, pg, pb);
                    }
                    html_escape_char(out_fp, ch);
                    fprintf(out_fp, "</span>");
                } else {
                    html_escape_char(out_fp, ch);
                }
            } else {
                /* Text output */
                if (opts.colors && !opts.grayscale) {
                    /* RGB color mode */
                    if (is_grayscale) {
                        /* 1-component: special bold/white handling */
                        if (lum_int == 0) {
                            fprintf(out_fp, "\033[37m%c\033[0m", ch);
                        } else if (lum_int >= 243) {
                            fprintf(out_fp, "\033[1m%c\033[0m", ch);
                        } else {
                            fputc(ch, out_fp);
                        }
                    } else {
                        /* 3-component: RGB color */
                        const char *code = get_ansi_color(pr, pg, pb);
                        fprintf(out_fp, "\033[%sm%c\033[0m", code, ch);
                    }
                } else if (opts.grayscale) {
                    /* Grayscale color mode */
                    if (lum_int >= 179) {
                        fprintf(out_fp, "\033[37m%c\033[0m", ch);
                    } else {
                        fputc(ch, out_fp);
                    }
                } else {
                    fputc(ch, out_fp);
                }
            }
        }

        if (opts.html) {
            fprintf(out_fp, "<br/>");
        } else {
            if (opts.border) fputc('|', out_fp);
            fputc('\n', out_fp);
        }
    }

    if (opts.html) fprintf(out_fp, "\n");

    /* Border bottom */
    if (opts.border && !opts.html) {
        fprintf(out_fp, "+");
        for (int x = 0; x < out_w; x++) fputc('-', out_fp);
        fprintf(out_fp, "+\n");
    }

    /* HTML footer */
    if (opts.html && !opts.html_raw) {
        html_footer(out_fp);
    }

    free(r_sum); free(g_sum); free(b_sum); free(cnt);
    free(lum_buf); free(r_avg); free(g_avg); free(b_avg);
    free(row_buf);
    return ret;
}

