/*
 * jp2a - JPEG to ASCII art converter
 * Reimplementation of jp2a 1.0.8
 * 
 * Algorithm discovered through reverse engineering:
 * - For each output pixel, accumulates source pixels with boundary sharing
 * - Rows: ALL-BACKWARD sharing (boundary rows share with previous output row)
 * - Cols: ASYMMETRIC sharing (backward for first half, forward for second half)
 * - Luminance: 0.2989*R + 0.5866*G + 0.1145*B
 * - Palette: "   ...',;:clodxkO0KXNWM"
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <setjmp.h>
#include <stdint.h>
#include <math.h>
#include <sys/ioctl.h>
#include <unistd.h>

/* ====== Minimal jpeglib definitions ====== */
typedef unsigned char JSAMPLE;
typedef JSAMPLE *JSAMPROW;
typedef JSAMPROW *JSAMPARRAY;
typedef unsigned int JDIMENSION;

typedef enum {
    JCS_UNKNOWN = 0, JCS_GRAYSCALE = 1, JCS_RGB = 2,
    JCS_YCbCr = 3, JCS_CMYK = 4, JCS_YCCK = 5
} J_COLOR_SPACE;

struct jpeg_error_mgr {
    void (*error_exit)(void *cinfo);
    void (*emit_message)(void *cinfo, int msg_level);
    void (*output_message)(void *cinfo);
    void (*format_message)(void *cinfo, char *buffer);
    void (*reset_error_mgr)(void *cinfo);
    int msg_code;
    union { int i[8]; char s[80]; } msg_parm;
    int trace_level;
    long num_warnings;
    const char * const *jpeg_message_table;
    int last_jpeg_message;
    const char * const *addon_message_table;
    int first_addon_message;
    int last_addon_message;
};

typedef struct {
    struct jpeg_error_mgr *err;
    void *mem;
    void *progress;
    void *client_data;
    int is_decompressor;
    int global_state;
    void *src;
    JDIMENSION image_width;
    JDIMENSION image_height;
    int num_components;
    J_COLOR_SPACE jpeg_color_space;
    J_COLOR_SPACE out_color_space;
    unsigned int scale_num;
    unsigned int scale_denom;
    int _pad76;
    double output_gamma;
    int buffered_image;
    int raw_data_out;
    int dct_method;
    int do_fancy_upsampling;
    int do_block_smoothing;
    int quantize_colors;
    int dither_mode;
    int two_pass_quantize;
    int desired_number_of_colors;
    int enable_1pass_quant;
    int enable_external_quant;
    int enable_2pass_quant;
    JDIMENSION output_width;
    JDIMENSION output_height;
    int out_color_components;
    int output_components;
    int rec_outbuf_height;
    int actual_number_of_colors;
    void *colormap;
    JDIMENSION output_scanline;
    char _pad[484];
} jpeg_decompress_struct;

struct my_error_mgr {
    struct jpeg_error_mgr pub;
    jmp_buf setjmp_buffer;
};

extern struct jpeg_error_mgr *jpeg_std_error(struct jpeg_error_mgr *err);
extern void jpeg_CreateDecompress(jpeg_decompress_struct *cinfo, int version, size_t structsize);
extern void jpeg_stdio_src(jpeg_decompress_struct *cinfo, FILE *infile);
extern int jpeg_read_header(jpeg_decompress_struct *cinfo, int require_image);
extern int jpeg_start_decompress(jpeg_decompress_struct *cinfo);
extern JDIMENSION jpeg_read_scanlines(jpeg_decompress_struct *cinfo, JSAMPARRAY scanlines, JDIMENSION max_lines);
extern int jpeg_finish_decompress(jpeg_decompress_struct *cinfo);
extern void jpeg_destroy_decompress(jpeg_decompress_struct *cinfo);

#define JPEG_LIB_VERSION 80
#define jpeg_create_decompress(cinfo) jpeg_CreateDecompress((cinfo), JPEG_LIB_VERSION, sizeof(jpeg_decompress_struct))

static void my_error_exit(void *cinfo_ptr) {
    jpeg_decompress_struct *cinfo = (jpeg_decompress_struct *)cinfo_ptr;
    struct my_error_mgr *myerr = (struct my_error_mgr *)cinfo->err;
    (*cinfo->err->output_message)(cinfo_ptr);
    longjmp(myerr->setjmp_buffer, 1);
}

/* ====== Constants ====== */
#define DEFAULT_PALETTE "   ...',;:clodxkO0KXNWM"
#define DEFAULT_PALETTE_LEN 23
#define ANSI_COLOR_THRESHOLD 26

/* ====== Options ====== */
static struct {
    int width, height;
    int use_width, use_height;
    int term_fit, term_width_flag, term_height_flag, term_zoom;
    int border, invert, flipx, flipy;
    int verbose, html, html_raw, html_fill, html_no_bold;
    int html_fontsize;
    char *html_title;
    int colors, grayscale, clear, debug;
    const char *palette;
    int palette_len;
    float red_weight, green_weight, blue_weight;
    char *output_file;
    int background_light;
} opts;

/* ====== Progress bar ====== */
static int progress_bar_width = 54;

static void print_progress(int current, int total) {
    int filled = (total > 0) ? (int)((float)current * progress_bar_width / total) : 0;
    if (filled > progress_bar_width) filled = progress_bar_width;
    fprintf(stderr, "\rDecompressing image [");
    for (int i = 0; i < progress_bar_width; i++)
        fputc(i < filled ? '#' : '.', stderr);
    fprintf(stderr, "]");
}

/* ====== Terminal size ====== */
static int get_term_size(int *w, int *h) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0) {
        *w = ws.ws_col;
        *h = ws.ws_row;
        return 1;
    }
    return 0;
}

/* ====== Dimension calculation ====== */
static void calc_dimensions(int src_w, int src_h, int *out_w, int *out_h) {
    int border_adj = opts.border ? 2 : 0;

    if (opts.term_zoom) {
        int tw, th;
        if (get_term_size(&tw, &th)) {
            *out_w = tw - border_adj;
            *out_h = th - border_adj;
        } else {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = *out_h = 0;
        }
        return;
    }

    if (opts.term_fit) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = *out_h = 0;
            return;
        }
        tw -= border_adj; th -= border_adj;
        if (tw < 1) tw = 1;
        if (th < 1) th = 1;
        /* Fit in terminal with 2:1 char aspect ratio */
        float aspect = (float)src_w / src_h;
        int h_from_w = (int)(tw / aspect / 2.0f + 0.5f);
        int w_from_h = (int)(th * aspect * 2.0f + 0.5f);
        if (h_from_w <= th) {
            *out_w = tw; *out_h = h_from_w;
        } else {
            *out_w = w_from_h; *out_h = th;
        }
        if (*out_w < 1) *out_w = 1;
        if (*out_h < 1) *out_h = 1;
        return;
    }

    if (opts.term_width_flag) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = *out_h = 0;
            return;
        }
        *out_w = tw - border_adj;
        *out_h = (int)((float)*out_w * src_h / src_w / 2.0f + 0.5f);
        if (*out_h < 1) *out_h = 1;
        return;
    }

    if (opts.term_height_flag) {
        int tw, th;
        if (!get_term_size(&tw, &th)) {
            fprintf(stderr, "Environment variable TERM not set.\n");
            *out_w = *out_h = 0;
            return;
        }
        *out_h = th - border_adj;
        *out_w = (int)((float)*out_h * src_w / src_h * 2.0f + 0.5f);
        if (*out_w < 1) *out_w = 1;
        return;
    }

    if (opts.use_width && opts.use_height) {
        *out_w = opts.width; *out_h = opts.height;
        return;
    }
    if (opts.use_width) {
        *out_w = opts.width;
        *out_h = (int)((float)opts.width * src_h / src_w / 2.0f + 0.5f);
        if (*out_h < 1) *out_h = 1;
        return;
    }
    if (opts.use_height) {
        *out_h = opts.height;
        *out_w = (int)((float)opts.height * src_w / src_h * 2.0f + 0.5f);
        if (*out_w < 1) *out_w = 1;
        return;
    }

    /* Default: term_fit */
    opts.term_fit = 1;
    calc_dimensions(src_w, src_h, out_w, out_h);
    opts.term_fit = 0;
}

/* ====== Color ====== */
static const char *get_ansi_color(int r, int g, int b) {
    int mn = r, mx = r;
    if (g < mn) mn = g; if (g > mx) mx = g;
    if (b < mn) mn = b; if (b > mx) mx = b;

    if (mx - mn < ANSI_COLOR_THRESHOLD) return "37";

    int r_near = (mx - r < ANSI_COLOR_THRESHOLD);
    int g_near = (mx - g < ANSI_COLOR_THRESHOLD);
    int b_near = (mx - b < ANSI_COLOR_THRESHOLD);

    if (r_near && g_near && !b_near) return "33"; /* yellow */
    if (r_near && b_near && !g_near) return "35"; /* magenta */
    if (g_near && b_near && !r_near) return "36"; /* cyan */
    if (r_near && !g_near && !b_near) return "31"; /* red */
    if (g_near && !r_near && !b_near) return "32"; /* green */
    if (b_near && !r_near && !g_near) return "34"; /* blue */
    return "37";
}

/* ====== HTML helpers ====== */
static void html_header(FILE *out) {
    fprintf(out, "<?xml version='1.0' encoding='ISO-8859-1'?>\n");
    fprintf(out, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n");
    fprintf(out, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n");
    fprintf(out, "<head>\n");
    fprintf(out, "<title>%s</title>\n", opts.html_title ? opts.html_title : "jp2a converted image");
    fprintf(out, "<style type='text/css'>\n");
    fprintf(out, "body {\n");
    if (opts.background_light)
        fprintf(out, "   background-color: white;\n");
    else
        fprintf(out, "background-color: black;\n");
    fprintf(out, "}\n");
    fprintf(out, ".ascii {\n");
    fprintf(out, "   font-family: Courier;\n");
    if (!opts.colors && !opts.grayscale) {
        if (opts.background_light)
            fprintf(out, "   color: black;\n");
        else
            fprintf(out, "   color: white;\n");
    }
    fprintf(out, "   font-size:%dpt;\n", opts.html_fontsize);
    if (opts.html_no_bold)
        fprintf(out, "   font-weight: normal;\n");
    else
        fprintf(out, "   font-weight: bold;\n");
    fprintf(out, "}\n");
    fprintf(out, "</style>\n");
    fprintf(out, "</head>\n");
    fprintf(out, "<body>\n");
    fprintf(out, "<div class='ascii'><pre>\n");
}

static void html_footer(FILE *out) {
    fprintf(out, "</pre>\n</div>\n</body>\n</html>\n");
}

static void html_escape_char(FILE *out, char c) {
    if (c == ' ') fprintf(out, "&nbsp;");
    else if (c == '<') fprintf(out, "&lt;");
    else if (c == '>') fprintf(out, "&gt;");
    else if (c == '&') fprintf(out, "&amp;");
    else fputc(c, out);
}

/* ====== Main image processing ====== */
static int process_image(const char *filename, FILE *in_fp, FILE *out_fp) {
    jpeg_decompress_struct cinfo;
    struct my_error_mgr jerr;
    int ret = 0;

    cinfo.err = jpeg_std_error(&jerr.pub);
    jerr.pub.error_exit = my_error_exit;

    if (setjmp(jerr.setjmp_buffer)) {
        jpeg_destroy_decompress(&cinfo);
        return 1;
    }

    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, in_fp);
    jpeg_read_header(&cinfo, 1);

    int src_w = cinfo.image_width;
    int src_h = cinfo.image_height;
    int src_comps = cinfo.num_components;
    int is_grayscale = (cinfo.num_components == 1);

    int out_w = 0, out_h = 0;
    calc_dimensions(src_w, src_h, &out_w, &out_h);

    if (out_w <= 0 || out_h <= 0) {
        jpeg_destroy_decompress(&cinfo);
        return 1;
    }

    if (opts.verbose) {
        if (filename) fprintf(stderr, "File: %s\n", filename);
        fprintf(stderr, "Source width: %d\n", src_w);
        fprintf(stderr, "Source height: %d\n", src_h);
        fprintf(stderr, "Source color components: %d\n", src_comps);
        fprintf(stderr, "Output width: %d\n", out_w);
        fprintf(stderr, "Output height: %d\n", out_h);
        fprintf(stderr, "Output palette (%d chars): '%s'\n", opts.palette_len, opts.palette);
    }

    jpeg_start_decompress(&cinfo);

    int dec_w = cinfo.output_width;
    int dec_h = cinfo.output_height;
    int dec_comps = cinfo.output_components;

    /* Allocate accumulators */
    long *r_sum = calloc(out_h * out_w, sizeof(long));
    long *g_sum = calloc(out_h * out_w, sizeof(long));
    long *b_sum = calloc(out_h * out_w, sizeof(long));
    int *cnt = calloc(out_h * out_w, sizeof(int));

    JSAMPROW row_buf = (JSAMPROW)malloc(dec_w * dec_comps);
    JSAMPARRAY row_ptr = &row_buf;

    int src_h_mid = dec_h / 2;
    int out_h_mid = out_h / 2;
    int src_w_mid = dec_w / 2;
    int out_w_mid = out_w / 2;

    /* Read all source rows */
    for (int i = 0; i < dec_h; i++) {
        if (opts.verbose) {
            print_progress(i, dec_h);
        }

        jpeg_read_scanlines(&cinfo, row_ptr, 1);

        int out_y = i * out_h / dec_h;
        /* ROW: ALL-BACKWARD sharing */
        int row_bkwd = (i * out_h % dec_h == 0) && (out_y > 0);

        for (int j = 0; j < dec_w; j++) {
            int out_x = j * out_w / dec_w;
            /* COL: ASYMMETRIC sharing */
            int col_bkwd = (j * out_w % dec_w == 0) && (out_x > 0) && (j <= src_w_mid);
            int col_fwd = ((j+1) * out_w % dec_w == 0) && (out_x < out_w-1) && (out_x >= out_w_mid);

            int r, g, b;
            if (dec_comps >= 3) {
                r = row_buf[j * dec_comps];
                g = row_buf[j * dec_comps + 1];
                b = row_buf[j * dec_comps + 2];
            } else {
                r = g = b = row_buf[j];
            }

#define ACCUM(oy, ox) do { \
    if ((oy) >= 0 && (oy) < out_h && (ox) >= 0 && (ox) < out_w) { \
        int _idx = (oy) * out_w + (ox); \
        r_sum[_idx] += r; g_sum[_idx] += g; b_sum[_idx] += b; cnt[_idx]++; \
    } \
} while(0)

            ACCUM(out_y, out_x);
            if (row_bkwd) ACCUM(out_y-1, out_x);
            if (col_bkwd) {
                ACCUM(out_y, out_x-1);
                if (row_bkwd) ACCUM(out_y-1, out_x-1);
            }
            if (col_fwd) {
                ACCUM(out_y, out_x+1);
                if (row_bkwd) ACCUM(out_y-1, out_x+1);
            }
        }
    }

    if (opts.verbose) {
        print_progress(dec_h, dec_h);
        fprintf(stderr, "\n");
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    /* Compute final pixel values */
    float *lum_buf = malloc(out_h * out_w * sizeof(float));
    int *r_avg = malloc(out_h * out_w * sizeof(int));
    int *g_avg = malloc(out_h * out_w * sizeof(int));
    int *b_avg = malloc(out_h * out_w * sizeof(int));

    for (int y = 0; y < out_h; y++) {
        for (int x = 0; x < out_w; x++) {
            int idx = y * out_w + x;
            int c = cnt[idx];
            if (c > 0) {
                r_avg[idx] = r_sum[idx] / c;
                g_avg[idx] = g_sum[idx] / c;
                b_avg[idx] = b_sum[idx] / c;
            } else {
                r_avg[idx] = g_avg[idx] = b_avg[idx] = 0;
            }
            lum_buf[idx] = opts.red_weight * r_avg[idx] + 
                           opts.green_weight * g_avg[idx] + 
                           opts.blue_weight * b_avg[idx];
        }
    }

    /* Clear screen */
    if (opts.clear && !opts.html) {
        fprintf(out_fp, "\033[2J\033[0;0H");
    }

    /* HTML header */
    if (opts.html && !opts.html_raw) {
        html_header(out_fp);
    }

    /* Border top */
    if (opts.border && !opts.html) {
        fprintf(out_fp, "+");
        for (int x = 0; x < out_w; x++) fputc('-', out_fp);
        fprintf(out_fp, "+\n");
    }

    /* Output image */
    for (int y = 0; y < out_h; y++) {
        if (opts.border && !opts.html) fputc('|', out_fp);

        for (int x = 0; x < out_w; x++) {
            int sx = opts.flipx ? (out_w - 1 - x) : x;
            int sy = opts.flipy ? (out_h - 1 - y) : y;
            int idx = sy * out_w + sx;

            float lum = lum_buf[idx];
            int lum_int = (int)(lum + 0.5f);
            if (lum_int < 0) lum_int = 0;
            if (lum_int > 255) lum_int = 255;

            /* Get palette index */
            int pal_idx = (int)round(lum * (opts.palette_len - 1) / 255.0f);
            if (pal_idx < 0) pal_idx = 0;
            if (pal_idx >= opts.palette_len) pal_idx = opts.palette_len - 1;
            if (opts.invert) pal_idx = opts.palette_len - 1 - pal_idx;
            char ch = opts.palette[pal_idx];

            int pr = r_avg[idx], pg = g_avg[idx], pb = b_avg[idx];
            if (opts.grayscale) { pr = pg = pb = lum_int; }

            if (opts.html) {
                if (opts.colors || opts.grayscale) {
                    if (opts.html_fill) {
                        /* Background color: slightly lighter version */
                        int bg_r = (pr * 2 + 255) / 3;
                        int bg_g = (pg * 2 + 255) / 3;
                        int bg_b = (pb * 2 + 255) / 3;
                        fprintf(out_fp, "<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>",
                                pr, pg, pb, bg_r, bg_g, bg_b);
                    } else {
                        fprintf(out_fp, "<span style='color:#%02x%02x%02x;'>", pr, pg, pb);
                    }
                    html_escape_char(out_fp, ch);
                    fprintf(out_fp, "</span>");
                } else {
                    html_escape_char(out_fp, ch);
                }
            } else {
                /* Text output */
                if (opts.colors && !opts.grayscale) {
                    /* RGB color mode */
                    if (is_grayscale) {
                        /* 1-component: special bold/white handling */
                        if (lum_int == 0) {
                            fprintf(out_fp, "\033[37m%c\033[0m", ch);
                        } else if (lum_int >= 243) {
                            fprintf(out_fp, "\033[1m%c\033[0m", ch);
                        } else {
                            fputc(ch, out_fp);
                        }
                    } else {
                        /* 3-component: RGB color */
                        const char *code = get_ansi_color(pr, pg, pb);
                        fprintf(out_fp, "\033[%sm%c\033[0m", code, ch);
                    }
                } else if (opts.grayscale) {
                    /* Grayscale color mode */
                    if (lum_int >= 179) {
                        fprintf(out_fp, "\033[37m%c\033[0m", ch);
                    } else {
                        fputc(ch, out_fp);
                    }
                } else {
                    fputc(ch, out_fp);
                }
            }
        }

        if (opts.html) {
            fprintf(out_fp, "<br/>");
        } else {
            if (opts.border) fputc('|', out_fp);
            fputc('\n', out_fp);
        }
    }

    if (opts.html) fprintf(out_fp, "\n");

    /* Border bottom */
    if (opts.border && !opts.html) {
        fprintf(out_fp, "+");
        for (int x = 0; x < out_w; x++) fputc('-', out_fp);
        fprintf(out_fp, "+\n");
    }

    /* HTML footer */
    if (opts.html && !opts.html_raw) {
        html_footer(out_fp);
    }

    free(r_sum); free(g_sum); free(b_sum); free(cnt);
    free(lum_buf); free(r_avg); free(g_avg); free(b_avg);
    free(row_buf);
    return ret;
}

/* ====== Help/version output ====== */
static void print_version(void) {
    fprintf(stdout, "jp2a 1.0.8\n");
    fprintf(stdout, "Copyright 2006-2016 Christian Stigen Larsen\n");
    fprintf(stdout, "Distributed under the GNU General Public License (GPL) v2.\n");
}

static void print_help(void) {
    print_version();
    fprintf(stdout, "\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n\n");
    fprintf(stdout, "Convert files or URLs from JPEG format to ASCII.\n\n");
    fprintf(stdout, "OPTIONS\n");
    fprintf(stdout, "  -                 Read images from standard input.\n");
    fprintf(stdout, "      --blue=N.N    Set RGB to grayscale conversion weight, default is 0.1145\n");
    fprintf(stdout, "  -b, --border      Print a border around the output image.\n");
    fprintf(stdout, "      --chars=...   Select character palette used to paint the image.\n");
    fprintf(stdout, "                    Leftmost character corresponds to black pixel, right-\n");
    fprintf(stdout, "                    most to white.  Minimum two characters must be specified.\n");
    fprintf(stdout, "      --clear       Clears screen before drawing each output image.\n");
    fprintf(stdout, "      --colors      Use ANSI colors in output.\n");
    fprintf(stdout, "  -d, --debug       Print additional debug information.\n");
    fprintf(stdout, "      --fill        When used with --color and/or --html, color each character's\n");
    fprintf(stdout, "                    background color.\n");
    fprintf(stdout, "  -x, --flipx       Flip image in X direction.\n");
    fprintf(stdout, "  -y, --flipy       Flip image in Y direction.\n");
    fprintf(stdout, "  -f, --term-fit    Use the largest image dimension that fits in your terminal\n");
    fprintf(stdout, "                    display with correct aspect ratio.\n");
    fprintf(stdout, "      --term-height Use terminal display height.\n");
    fprintf(stdout, "      --term-width  Use terminal display width.\n");
    fprintf(stdout, "  -z, --term-zoom   Use terminal display dimension for output.\n");
    fprintf(stdout, "      --grayscale   Convert image to grayscale when using --html or --colors\n");
    fprintf(stdout, "      --green=N.N   Set RGB to grayscale conversion weight, default is 0.5866\n");
    fprintf(stdout, "      --height=N    Set output height, calculate width from aspect ratio.\n");
    fprintf(stdout, "  -h, --help        Print program help.\n");
    fprintf(stdout, "      --html        Produce strict XHTML 1.0 output.\n");
    fprintf(stdout, "      --html-fill   Same as --fill (will be phased out)\n");
    fprintf(stdout, "      --html-fontsize=N   Set fontsize to N pt, default is 4.\n");
    fprintf(stdout, "      --html-no-bold      Do not use bold characters with HTML output\n");
    fprintf(stdout, "      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.\n");
    fprintf(stdout, "      --html-title=...  Set HTML output title\n");
    fprintf(stdout, "  -i, --invert      Invert output image.  Use if your display has a dark\n");
    fprintf(stdout, "                    background.\n");
    fprintf(stdout, "      --background=dark   These are just mnemonics whether to use --invert\n");
    fprintf(stdout, "      --background=light  or not.  If your console has light characters on\n");
    fprintf(stdout, "                    a dark background, use --background=dark.\n");
    fprintf(stdout, "      --output=...  Write output to file.\n");
    fprintf(stdout, "      --red=N.N     Set RGB to grayscale conversion weight, default 0.2989f.\n");
    fprintf(stdout, "      --size=WxH    Set output width and height.\n");
    fprintf(stdout, "  -v, --verbose     Verbose output.\n");
    fprintf(stdout, "  -V, --version     Print program version.\n");
    fprintf(stdout, "      --width=N     Set output width, calculate height from ratio.\n");
    fprintf(stdout, "\n");
    fprintf(stdout, "  The default mode is `jp2a --term-fit --background=dark'.\n");
    fprintf(stdout, "  See the man-page for jp2a for more detailed help text.\n");
    fprintf(stdout, "\n");
    fprintf(stdout, "Project homepage on https://github.com/cslarsen/jp2a\n");
    fprintf(stdout, "Report bugs to <csl@csl.name>\n");
}

/* ====== Main ====== */
int main(int argc, char **argv) {
    /* Set defaults */
    opts.width = 80; opts.height = 25;
    opts.use_width = opts.use_height = 0;
    opts.term_fit = opts.term_width_flag = opts.term_height_flag = opts.term_zoom = 0;
    opts.border = opts.invert = opts.flipx = opts.flipy = 0;
    opts.verbose = opts.html = opts.html_raw = opts.html_fill = opts.html_no_bold = 0;
    opts.html_fontsize = 4;
    opts.html_title = NULL;
    opts.colors = opts.grayscale = opts.clear = opts.debug = 0;
    opts.palette = DEFAULT_PALETTE;
    opts.palette_len = DEFAULT_PALETTE_LEN;
    opts.red_weight = 0.2989f;
    opts.green_weight = 0.5866f;
    opts.blue_weight = 0.1145f;
    opts.output_file = NULL;
    opts.background_light = 0;

    /* Parse options */
    int has_files = 0;
    FILE *out_fp = stdout;

    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];
        if (strcmp(arg, "--version") == 0 || strcmp(arg, "-V") == 0) {
            print_version(); return 0;
        } else if (strcmp(arg, "--help") == 0 || strcmp(arg, "-h") == 0) {
            print_help(); return 0;
        } else if (strcmp(arg, "--border") == 0 || strcmp(arg, "-b") == 0)
            opts.border = 1;
        else if (strcmp(arg, "--invert") == 0 || strcmp(arg, "-i") == 0)
            opts.invert = 1;
        else if (strcmp(arg, "--flipx") == 0 || strcmp(arg, "-x") == 0)
            opts.flipx = 1;
        else if (strcmp(arg, "--flipy") == 0 || strcmp(arg, "-y") == 0)
            opts.flipy = 1;
        else if (strcmp(arg, "--verbose") == 0 || strcmp(arg, "-v") == 0)
            opts.verbose = 1;
        else if (strcmp(arg, "--debug") == 0 || strcmp(arg, "-d") == 0)
            opts.debug = 1;
        else if (strcmp(arg, "--colors") == 0)
            opts.colors = 1;
        else if (strcmp(arg, "--grayscale") == 0)
            opts.grayscale = 1;
        else if (strcmp(arg, "--html") == 0)
            opts.html = 1;
        else if (strcmp(arg, "--html-raw") == 0) {
            opts.html_raw = 1; opts.html = 1;
        } else if (strcmp(arg, "--fill") == 0 || strcmp(arg, "--html-fill") == 0)
            opts.html_fill = 1;
        else if (strcmp(arg, "--html-no-bold") == 0)
            opts.html_no_bold = 1;
        else if (strcmp(arg, "--clear") == 0)
            opts.clear = 1;
        else if (strcmp(arg, "--term-fit") == 0 || strcmp(arg, "-f") == 0)
            opts.term_fit = 1;
        else if (strcmp(arg, "--term-width") == 0)
            opts.term_width_flag = 1;
        else if (strcmp(arg, "--term-height") == 0)
            opts.term_height_flag = 1;
        else if (strcmp(arg, "--term-zoom") == 0 || strcmp(arg, "-z") == 0)
            opts.term_zoom = 1;
        else if (strcmp(arg, "--zoom") == 0)
            opts.term_zoom = 1;
        else if (strncmp(arg, "--width=", 8) == 0) {
            opts.width = atoi(arg + 8); opts.use_width = 1;
        } else if (strncmp(arg, "--height=", 9) == 0) {
            opts.height = atoi(arg + 9); opts.use_height = 1;
        } else if (strncmp(arg, "--size=", 7) == 0) {
            int w, h;
            if (sscanf(arg + 7, "%dx%d", &w, &h) == 2) {
                opts.width = w; opts.height = h;
                opts.use_width = opts.use_height = 1;
            }
        } else if (strncmp(arg, "--chars=", 8) == 0) {
            opts.palette = arg + 8;
            opts.palette_len = strlen(opts.palette);
        } else if (strncmp(arg, "--html-fontsize=", 16) == 0)
            opts.html_fontsize = atoi(arg + 16);
        else if (strncmp(arg, "--html-title=", 13) == 0)
            opts.html_title = arg + 13;
        else if (strncmp(arg, "--output=", 9) == 0)
            opts.output_file = arg + 9;
        else if (strncmp(arg, "--red=", 6) == 0)
            opts.red_weight = (float)atof(arg + 6);
        else if (strncmp(arg, "--green=", 8) == 0)
            opts.green_weight = (float)atof(arg + 8);
        else if (strncmp(arg, "--blue=", 7) == 0)
            opts.blue_weight = (float)atof(arg + 7);
        else if (strcmp(arg, "--background=light") == 0) {
            opts.background_light = 1; opts.invert = 1;
        } else if (strcmp(arg, "--background=dark") == 0) {
            opts.background_light = 0;
        } else if (strcmp(arg, "-") == 0) {
            has_files = 1;
        } else if (arg[0] != '-') {
            has_files = 1;
        }
    }

    /* Open output file */
    if (opts.output_file) {
        if (strcmp(opts.output_file, "-") != 0) {
            out_fp = fopen(opts.output_file, "w");
            if (!out_fp) {
                fprintf(stderr, "Can't open %s for writing\n", opts.output_file);
                return 1;
            }
        }
    }

    /* Default mode: term-fit */
    if (!opts.term_fit && !opts.term_width_flag && !opts.term_height_flag &&
        !opts.term_zoom && !opts.use_width && !opts.use_height) {
        opts.term_fit = 1;
    }

    /* Check if we have any files */
    if (!has_files) {
        if (opts.term_fit || opts.term_width_flag || opts.term_height_flag || opts.term_zoom) {
            int tw, th;
            if (!get_term_size(&tw, &th)) {
                fprintf(stderr, "Environment variable TERM not set.\n");
                return 1;
            }
        }
        return 0;
    }

    /* Process files */
    int errors = 0;
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];

        /* Skip recognized flags */
        if (strcmp(arg, "--border") == 0 || strcmp(arg, "-b") == 0 ||
            strcmp(arg, "--invert") == 0 || strcmp(arg, "-i") == 0 ||
            strcmp(arg, "--flipx") == 0 || strcmp(arg, "-x") == 0 ||
            strcmp(arg, "--flipy") == 0 || strcmp(arg, "-y") == 0 ||
            strcmp(arg, "--verbose") == 0 || strcmp(arg, "-v") == 0 ||
            strcmp(arg, "--debug") == 0 || strcmp(arg, "-d") == 0 ||
            strcmp(arg, "--colors") == 0 || strcmp(arg, "--grayscale") == 0 ||
            strcmp(arg, "--html") == 0 || strcmp(arg, "--html-raw") == 0 ||
            strcmp(arg, "--fill") == 0 || strcmp(arg, "--html-fill") == 0 ||
            strcmp(arg, "--html-no-bold") == 0 || strcmp(arg, "--clear") == 0 ||
            strcmp(arg, "--term-fit") == 0 || strcmp(arg, "-f") == 0 ||
            strcmp(arg, "--term-width") == 0 || strcmp(arg, "--term-height") == 0 ||
            strcmp(arg, "--term-zoom") == 0 || strcmp(arg, "-z") == 0 ||
            strcmp(arg, "--zoom") == 0 ||
            strcmp(arg, "--background=light") == 0 || strcmp(arg, "--background=dark") == 0)
            continue;

        /* Skip options with values */
        if (strncmp(arg, "--width=", 8) == 0 || strncmp(arg, "--height=", 9) == 0 ||
            strncmp(arg, "--size=", 7) == 0 || strncmp(arg, "--chars=", 8) == 0 ||
            strncmp(arg, "--html-fontsize=", 16) == 0 || strncmp(arg, "--html-title=", 13) == 0 ||
            strncmp(arg, "--output=", 9) == 0 || strncmp(arg, "--red=", 6) == 0 ||
            strncmp(arg, "--green=", 8) == 0 || strncmp(arg, "--blue=", 7) == 0)
            continue;

        if (arg[0] == '-' && arg[1] == '-') continue; /* Unknown --option */

        /* stdin */
        if (strcmp(arg, "-") == 0) {
            errors += process_image("stdin", stdin, out_fp);
            continue;
        }

        /* Skip other single-char flags */
        if (arg[0] == '-' && arg[1] != '\0') continue;

        /* It's a filename */
        FILE *fp = fopen(arg, "rb");
        if (!fp) {
            fprintf(stderr, "Can't open %s\n", arg);
            errors++;
            continue;
        }
        errors += process_image(arg, fp, out_fp);
        fclose(fp);
    }

    if (opts.output_file && out_fp != stdout) {
        fclose(out_fp);
    }

    return errors ? 1 : 0;
}
